// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · İstatistiksel yanılgılar ve veri okuryazarlığı (kolay).
const ozStatistics13Kolay = <(String, String, List<String>, String)>[
  ('Hilesiz bir para 6 kez atılıyor. \'YYYYYY\' dizisinin gelme olasılığı ile \'YTTYTY\' dizisinin gelme olasılığı arasında nasıl bir ilişki vardır?', 'İkisinin olasılığı da eşittir ve her biri 1/64\'tür', ['YTTYTY daha olasıdır, çünkü karışık diziler daha doğal görünür', 'YYYYYY daha olasıdır, çünkü tek bir yüzün tekrarı tek bir örüntüdür', 'Karşılaştırma yapılamaz, çünkü dizilerin uzunluğu çok kısadır'], 'Her atış bağımsızdır ve her belirli dizi (1/2)^6 = 1/64 olasılıkla gelir. Karışık görünen dizilerin çok sayıda olması, belirli bir dizinin daha olası olduğu anlamına gelmez.'),
  ('Bir kişi ahırın duvarına gözü kapalı ateş ediyor, kurşun deliklerinin en yoğun olduğu yerin çevresine sonradan hedef tahtası çiziyor ve kendine \'keskin nişancı\' diyor. İstatistiksel çıkarım hatası olarak bu durum nasıl adlandırılır?', 'Texas keskin nişancı yanılgısı', ['Kumarbaz yanılgısı, yani geçmiş sonucun geleceği etkilediğine inanmak', 'Hayatta kalma yanlılığı', 'Ekolojik yanılgı'], 'Hipotez (hedef), veriler görüldükten sonra verilere göre belirlenmektedir. Rastgele kümeler sonradan \'anlamlı\' gösterilir; hipotez veriden önce kurulmalıdır.'),
  ('Bir müzik çalar \'karışık çalma\' modunda rastgele şarkı seçerken aynı sanatçıdan art arda iki şarkı çalınca kullanıcı \'bu rastgele olamaz\' diyor. Bu şikayet için en doğru değerlendirme hangisidir?', 'Rastgele seçimde de ardışık tekrarlar olur; kullanıcı düzenli dağılımı rastgelelik sanıyor', ['Gerçek rastgele seçimde aynı sanatçı hiçbir zaman art arda gelmez, çünkü her seçim öncekinden farklı olur', 'Rastgele seçimde ardışık tekrarların olması cihazın bozuk olduğunu kanıtlar', 'Rastgele seçim ancak şarkı sayısı sonsuz olduğunda tekrarlar içerir'], 'Bağımsız seçimlerde aynı öğenin art arda gelmesi beklenen bir durumdur. İnsanlar düzgün aralıklı dağılımı rastgele sandığı için küme görünce kuşkulanır.'),
  ('Hilesiz bir paranın ilk 10 atışında 8 yazı geldi. Büyük sayılar yasasını doğru uygulayan yorum hangisidir?', 'Sonraki atışlar bu fazlalığı telafi etmez; fazlalık atış sayısı arttıkça oran içinde seyrelir', ['Sonraki atışlarda tura gelme olasılığı artarak dengeyi geri getirir, çünkü yasa sapmaları sonraki atışlarda giderir', 'Para artık hilesiz sayılamaz ve yazıya doğru yanlıdır', 'Bir sonraki atışın yazı gelme olasılığı 8/10\'a yükselir'], 'Atışlar bağımsızdır ve paranın belleği yoktur. Oran 0,5\'e yaklaşır, çünkü sonraki çok sayıdaki atış ilk 10\'luk sapmayı etkisiz kılar; telafi mekanizması yoktur.'),
  ('Bir bölgede 4 kişiye uygulanan bir diyetin ardından kişilerin üçünün kilo verdiği görülüyor ve diyet \'etkili\' ilan ediliyor. Bu sonuca güvenmeyi zorlaştıran temel etken hangisidir?', 'Örneklemin çok küçük olması nedeniyle sonucun şansla ortaya çıkma olasılığının yüksek olması', ['Kilo verenlerin sayısının kilo vermeyenlerden fazla olması, çünkü bu çoğunluk etkiyi kanıtlar', 'Diyetin yalnızca yetişkinlere uygulanmış olması', 'Sonucun yüzde olarak değil sayı olarak verilmesi'], 'Dört kişilik bir grupta üçünün kilo vermesi şansla kolayca görülür. Küçük örneklemlerde oranlar çok oynaktır; sonucun kesinliği ancak daha büyük örneklemlerle sağlanabilir.'),
  ('Bir kentte 8 milyon kişi yaşıyor ve her gün her kişi için bağımsız olarak milyonda bir olasılıkla \'sıra dışı\' bir rastlantı ortaya çıkıyor. Bu kentte günde yaklaşık kaç kişi böyle bir olay yaşar?', 'Yaklaşık 8 kişi', ['Yaklaşık 1 kişi', 'Hemen hemen hiç kimse', 'Yaklaşık 80 kişi'], 'Beklenen sayı 8.000.000 × 1/1.000.000 = 8\'dir. Diaconis ile Mosteller\'in \'gerçekten büyük sayılar yasası\'na göre yeterince büyük bir topluluğa bakıldığında çok nadir olaylar da düzenli olarak görülür.'),
  ('Bir kâğıt üzerinde rastgele 100 nokta işaretlenen kareye bakan kişi, noktaların bazı yerlerde \'topaklandığını\' söylüyor. Düzgün ve eşit aralıklı dağılımın aksine, bu topaklanma neyi gösterir?', 'Tamamen rastgele yerleştirmelerde de tipik olarak boşluklar ve topaklar oluşur', ['Noktaların kesin biçimde bir mıknatıs etkisiyle yerleştirildiğini, çünkü topaklar şansla oluşmaz', 'Noktaların ancak insan eliyle işaretlenebileceğini', 'Karenin yarısının mutlaka boş kalacağını'], 'Rastgele süreçler düzgün dağılım üretmez; topaklar ve boşluklar beklenen özelliklerdir. Düzgün aralıklı yerleşim, tersine, bilinçli bir düzenin işaretidir.'),
  ('Birisi \'Eski evler çok sağlam yapılırdı; yüz yıllık binaların çoğu hâlâ ayakta, yenilerse hemen yıkılıyor\' diyor. Bu çıkarımdaki temel istatistiksel sorun nedir?', 'Yalnızca yıkılmadan günümüze ulaşan sağlam yapılar görülmekte, yıkılan zayıf yapılar sayıma girmemektedir', ['Eski binaların sayısının yeni binalardan hep daha fazla olması, çünkü sayının fazlalığı dayanıklılığı gösterir', 'Yüz yıllık binaların örneklem olarak çok küçük bir yaş grubu olması', 'Binaların dayanıklılığının yalnızca kullanılan malzemeye bağlı olması'], 'Zaman içinde elenen yapılar gözlemlenemez; gözlenen eski binalar seçilmiş, dayanıklı olanlardır. Bu durum, eski yapıların ortalamada daha sağlam olduğu sonucunu yanlışlıkla destekler.'),
  ('Bir müzik eleştirmeni \'Eski kuşağın şarkıları çok daha kaliteliydi, hâlâ çalınıyorlar\' diyor. Bu karşılaştırmanın hangi yanlılıktan etkilendiği söylenebilir?', 'Yalnızca zamanın elemesinden geçen iyi şarkılar hatırlandığı için hayatta kalma yanlılığından', ['Yeni şarkıların sayısının eski şarkılardan çok az olmasından, çünkü yeni dönemde şarkı üretimi durmuştur', 'Eski şarkıların her zaman daha uzun olmasından', 'Şarkıların yalnızca radyolarda çalınmasından'], 'Dönemin vasat şarkıları unutulmuş, geriye seçilmiş iyiler kalmıştır. Yeni dönemin şarkıları ise henüz elenmemiş, tüm kalite aralığıyla görünmektedir.'),
  ('Bir araştırmada kırmızı şarap içenlerin kalp hastalığı oranı içmeyenlerden düşük bulunuyor. Gözlemsel bu bulguda şarabın etkisinin abartılmasına yol açabilecek en olası karıştırıcı hangisidir?', 'Şarap içenlerin ortalamada gelir ve beslenme düzeyinin yüksek olması', ['Şarabın şişe rengi, çünkü renk tercihi içki ve sağlık davranışını etkiler', 'İçilen şarabın tadı', 'Araştırmanın yapıldığı mevsim'], 'Gelir, eğitim ve beslenme gibi etkenler hem şarap tercihini hem kalp sağlığını etkileyebilir. Bu etkenler kontrol edilmedikçe şarabın bağımsız etkisi saptanamaz.'),
  ('Karıştırıcı değişkenin etkisini deneysel çalışmada en güçlü biçimde dengelemek için hangi yöntem kullanılır?', 'Katılımcıları gruplara rastgele atamak', ['Katılımcıların gruplarını kendilerinin seçmesine izin vermek', 'Sadece tek bir gruba uygulama yapmak', 'Ölçümleri yalnızca bir kez almak'], 'Rastgele atama, bilinen ve bilinmeyen karıştırıcıların gruplar arasında ortalamada eşit dağılmasını sağlar. Gözlemsel çalışmalarda ise ancak ölçülmüş değişkenler istatistiksel olarak ayarlanabilir.'),
  ('Bir şehirde yıl boyunca yangına çağrılan itfaiye araç sayısı ile yangın hasarının parasal büyüklüğü arasında güçlü bir pozitif ilişki bulunuyor. \'Daha çok itfaiye aracı daha çok hasar verir\' sonucu neden yanlıştır?', 'Yangının büyüklüğü hem gönderilen araç sayısını hem hasarı belirler', ['İtfaiye araçlarının kayıtlarının kâğıtta tutulması, çünkü kâğıt kayıtlar yanlış sayıma yol açar', 'Hasarın parayla ölçülmesinin hatalı olması', 'Araç sayısının ancak çift sayı olabilmesi'], 'Büyük yangınlar daha fazla araç çağrılmasına ve daha fazla hasara yol açar. Ortak neden (yangın büyüklüğü) iki değişkeni de etkileyerek sahte bir nedensellik izlenimi oluşturur.'),
  ('Bir mağaza, etiket fiyatına önce %20 indirim yapıyor, kasada ise indirimli fiyata ayrıca %20 daha indirim uyguluyor. Toplam indirim oranı kaçtır?', '%36', ['%40, çünkü iki indirim toplanır', '%32', '%20'], 'Fiyat 0,80 × 0,80 = 0,64 katına iner, yani toplam indirim %36\'dır. Ardışık yüzdeler toplanmaz, çarpılır.'),
  ('Bir çalışanın maaşı önce %10 azaltılıyor, bir süre sonra %10 artırılıyor. Son maaş ilk maaşın yüzde kaçıdır?', '%99', ['%100', '%101', '%98'], '0,90 × 1,10 = 0,99\'dur; maaş ilk değerin %99\'una iner. Aynı yüzdeyle artış ve azalış, farklı tabanlar nedeniyle birbirini tam sıfırlamaz.'),
  ('Bir şirketin ürünü A, B\'ye göre %50 daha pahalıdır. B ürünü A\'dan yüzde kaç daha ucuzdur?', 'Yaklaşık %33,3', ['%50, çünkü yüzde farkın tabanı iki ürün için aynıdır', '%25', '%66,7'], 'B = 100 ise A = 150\'dir; B\'nin A\'dan farkı 50/150 ≈ %33,3\'tür. Yüzde farkın yönü değişince taban da değişir.'),
  ('Etiketinde \'%20 indirimli\' yazan bir ürün 160 TL\'ye satılıyor. Ürünün indirimsiz fiyatı kaçtır?', '200 TL', ['192 TL, çünkü indirim tutarı fiyata eklenir', '180 TL', '210 TL'], 'İndirimli fiyat, indirimsiz fiyatın %80\'idir; 160 / 0,80 = 200 TL. 160\'ın %20\'sini eklemek (192 TL) yaygın bir yanlış tabandır.'),
  ('Kontrol grubunda 100 kişiden 20\'si, tedavi grubunda 100 kişiden 15\'i hastalanıyor. Göreli risk azalması ve mutlak risk azalması sırasıyla nedir?', '%25 ve 5 yüzde puan', ['%5 ve 25 yüzde puan', '%15 ve 20 yüzde puan', '%33 ve 5 yüzde puan'], 'Mutlak azalma 0,20 − 0,15 = 0,05 yani 5 puandır; göreli azalma 0,05 / 0,20 = %25\'tir.'),
  ('Bir ilacın yan etkisi 1000 kişide 1\'den 2\'ye çıkıyor ve haber \'Yan etki riski %100 arttı\' diyor. Bu durumda ilacı kullanan her 1000 kişide kaç kişide ek yan etki beklenir?', '1 kişi', ['100 kişi', '10 kişi', '2 kişi'], 'Mutlak artış binde 2 − binde 1 = binde 1\'dir. %100 göreli artış, çok küçük bir temel riskten kaynaklandığı için mutlak olarak küçük kalır.'),
  ('Bir nehrin ortalama derinliği 1 metre olarak ölçülmüştür ve bir gezgin \'yürüyerek geçilebilir\' sonucuna varıyor. Bu çıkarım için en doğru eleştiri nedir?', 'Ortalama derin çukurları gizler; dağılım bilinmeden güvenli sonuç çıkmaz', ['Ortalama derinlik yalnız suyun akış hızıyla birlikte anlam taşır, ve akış hızı olmadan ölçüm geçersizdir', 'Nehirlerin derinliği hiçbir zaman ölçülemez', 'Derinlik yalnızca metre değil santimetre cinsinden ifade edilmelidir'], 'Ortalama tek bir sayıyla değişkenliği gizler: kıyıda 20 cm, ortada 3 metre derinlik de ortalama 1 metre verebilir. Karar için yayılım bilgisi gereklidir.'),
  ('Bir okulda 20 öğrencilik A sınıfının matematik ortalaması 80, 30 öğrencilik B sınıfının ortalaması 60\'tır. İki sınıf birleştirildiğinde ortalama için hangisi doğrudur?', '68\'dir; ortalamaların basit ortalaması alınamaz', ['70\'tir; çünkü iki ortalamanın aritmetik ortalaması alınır', '66\'dır; çünkü küçük sınıfın etkisi daha fazladır', '75\'tir; çünkü yüksek ortalama sonucu belirler'], 'Toplam puan 20×80 + 30×60 = 3400, öğrenci sayısı 50; ortalama 68\'dir. Ortalamaların ortalaması ancak grupların büyüklükleri eşitse doğrudur.'),
  ('Etkisiz 20 maddenin her biri için bağımsız testler yapılırken Bonferroni düzeltmesiyle toplam anlamlılık düzeyi %5\'te tutulmak isteniyorsa her bir testte hangi eşik kullanılır?', '0,0025', ['0,05, çünkü düzeltme eşiği değiştirmez', '0,01', '0,25'], 'Bonferroni düzeltmesinde eşik, toplam düzeyin test sayısına bölünmesiyle bulunur: 0,05 / 20 = 0,0025.'),
  ('Bir internet şirketi, 2 milyon kullanıcılı bir denemede yeni düğme rengi ile ortalama oturum süresinde 0,3 saniyelik artış buluyor ve p < 0,001. Bu sonuç hakkında hangisi doğrudur?', 'İstatistiksel olarak anlamlıdır ancak pratik önemi küçük olabilir', ['Etki çok büyüktür, çünkü p-değeri çok küçüktür, ve örneklem büyüklüğü önemsizdir', 'Sonuç, örneklem büyük olduğu için güvenilmezdir', 'Pratik önem ancak p-değeri 0,05 ise ortaya çıkar'], 'Çok büyük örneklemlerde küçücük farklar bile anlamlı çıkar; p-değeri etkinin büyüklüğünü ölçmez. Kararda etki büyüklüğü ve maliyet de değerlendirilmelidir.'),
  ('Araştırma hipotezini, yöntemini ve analiz planını veri toplamadan önce kamuya açık bir kayda yazmaya ne ad verilir ve hangi sorunu azaltmayı hedefler?', 'Ön kayıt; p-hacking ve sonradan hipotez kurmayı azaltmayı', ['Meta-analiz; örneklem sayısını artırmayı ve ölçüm hatasını azaltmayı', 'Rastgele atama; ölçüm hatasını sıfırlamayı', 'Ön test; katılımcıları eşleştirmeyi'], 'Ön kayıt, analiz esnekliğini sınırlayarak raporlanan p-değerlerinin yorumlanabilirliğini artırır. Önceden belirlenmiş ve keşfedici analizler birbirinden ayrılır.'),
  ('Her biri etkisiz 100 gen için ayrı testler yapılıyor ve her testte anlamlılık düzeyi %5 alınıyor. Düzeltme yapılmazsa \'anlamlı\' çıkması beklenen gen sayısı yaklaşık kaçtır?', 'Yaklaşık 5', ['Yaklaşık 0', 'Yaklaşık 50', 'Yaklaşık 95'], 'Her etkisiz testin yanlış pozitif olasılığı 0,05\'tir; beklenen sayı 100 × 0,05 = 5\'tir. Düzeltme olmadan bu yanlış pozitifler \'keşif\' olarak raporlanabilir.'),
  ('Bir fon reklamı \'Son 3 yılda piyasa ortalamasının %12 üzerinde getiri sağladık\' diyor; fon 10 yıldır var ve ilk yedi yılda piyasanın altında kalmıştır. Reklamdaki bu seçimin adı nedir?', 'Kiraz toplama; yalnızca lehine sonuç veren dönem gösterilmiştir', ['Kapsam hatası; yalnızca fonun büyüklüğü hesaplanmıştır', 'Yanıtsızlık yanlılığı; yatırımcıların bir kısmı ankete cevap vermemiştir', 'Ekolojik yanılgı; grup ortalaması bireye uygulanmıştır'], 'Başlangıç ve bitiş yılı seçilerek hemen her fon için parlak bir dönem bulunabilir. Güvenilir bir değerlendirme, fonun tüm geçmişini ve ölçüt olarak aynı dönemi gerektirir.'),
  ('Bir kafe zinciri \'Müşterilerimizin %90\'ı bizden memnun\' diyor. Gerçekte 10 bin müşteriye sorulmuş, en memnun görünen 100 yanıt rapora alınmış. Bu raporlama için en uygun değerlendirme hangisidir?', 'Yanlıdır; yanıtlar önceden en olumlu olanlar arasından seçilmiştir', ['Güvenilirdir; çünkü 100 yanıt sayısal bir örneklem oluşturur', 'Güvenilirdir; çünkü yüzde 90 yüksek bir oran olduğundan hatalı olamaz', 'Yanlıdır; çünkü memnuniyet oranları yüzde olarak verilmemelidir'], 'Seçim, sonucu yansıtmayan olumlu bir alt kümeye dayandığı için oran şişirilmiştir. Anket sonuçları, yanıtların tümü ya da rastgele bir örneği üzerinden raporlanmalıdır.'),
  ('Bir kişi \'Dayım yıllarca sigara içti ve 95 yaşına kadar yaşadı; sigaranın zararı abartılıyor\' diyor. Bu çıkarım hakkında hangisi doğrudur?', 'Tek bir vaka olasılıksal bir riski çürütemez', ['Tek vaka çürütmeye yeter, çünkü istisnalar kuralı bozar', 'Dayının yaşı sigara riskinin hiç olmadığını kanıtlar', 'Sigara riskinin ancak bir kişiyle ölçülebileceğini gösterir'], 'Sigara, bireylerde kesin bir sonuç değil, topluluk düzeyinde belirgin bir ölüm riski artışı yaratır. Anekdotlar, bu tür olasılıksal ilişkileri çürütmek için yetersiz kanıttır.'),
  ('Bir kişi \'Şu bitki çayını içen komşum soğuk algınlığından üç günde iyileşti, çay işe yarıyor\' diyor. Bu iddiayı değerlendirmek için hangi bilgi eksiktir?', 'Çay içmeyen benzer hastaların da iyileşip iyileşmediği', ['Çayın hangi markadan satın alındığı, ve ne kadar demlendiği ile kaç bardak içildiği', 'Komşunun çayı hangi saatte içtiği', 'Çay bitkisinin hangi bölgede yetiştiği'], 'Soğuk algınlığı çoğu kez kendiliğinden geçer; kontrol edilmemiş bir vaka etkiyi ayırt edemez. Karşılaştırma için çay içmeyenlerin iyileşme süresi bilinmelidir.'),
  ('Bir falcı, \'30 yaş civarında önemli bir değişiklik yaşayacaksınız, bazen kendinize güvensiz hissediyorsunuz\' gibi herkese uyan cümleler söylüyor ve kişiler büyük oranda kendilerine uygun buluyor. Bu eğilim hangi adla anılır?', 'Barnum (Forer) etkisi', ['Hawthorne etkisi, yani gözlenmenin davranışı değiştirmesi', 'Plasebo etkisi', 'Goodhart etkisi'], 'Genel ve belirsiz betimlemeler, kişinin onları kendine özgü sanması nedeniyle doğrulanmış görünür. Bertram Forer, 1948\'de öğrencilere aynı metni verip kişisel diye değerlendirttiğinde yüksek puanlar elde etti.'),
  ('Bir market, kıymayı \'%90 yağsız\' diye ve başka bir market aynı ürünü \'%10 yağlı\' diye etiketliyor. Tüketicilerin ilkini daha kaliteli bulması hangi etkiyle açıklanır?', 'Çerçeveleme etkisi', ['Büyük sayılar yasası', 'Hayatta kalma yanlılığı', 'Ortalamaya dönüş'], 'İki ifade matematiksel olarak aynı bilgidir; ancak olumlu söylenen ifade daha iyi algılanır. Sunum biçimi, aynı veri üzerinden farklı kararlara yol açabilir.'),
  ('Bir satıcı, 2.000 TL olarak etiketlenmiş bir ürünün üstünü çizip 1.200 TL yazıyor. İlk fiyatın alıcının algıladığı \'değer\' üzerindeki etkisi en iyi hangi kavramla açıklanır?', 'Çıpalama', ['Hayatta kalma yanlılığı', 'Kümelenme yanılsaması', 'Yanıtsızlık yanlılığı'], 'Yüksek ilk fiyat, referans noktası olur ve ardından gelen fiyat \'ucuz\' görünür. Karşılaştırma yapılmadan önce o referansın geçerliliği sorgulanmalıdır.'),
  ('Bir kentte polis sayısı fazla olan mahallelerde suç sayısının da fazla olduğu gözleniyor. Bu ilişki için aşağıdaki açıklamalardan hangisi, polisin suçu artırdığı sonucunu çıkarmadan makul bir yorum sunar?', 'Suçun yüksek olduğu mahallelere daha fazla polis gönderiliyordur', ['Polislerin suç sayısını artırmak için mahalleleri seçiyor olması', 'Suç sayısının polis sayısından hiç etkilenmediğinin kanıtlanmış olması', 'Polis sayısının yalnızca yaz aylarında ölçülmüş olması'], 'Kaynakların tehlikeli bölgelere kaydırılması, nedensel yönü tersine çevirir: suç polisi çeker. Bu nedenle yalın korelasyon polisin suçu artırdığına kanıt değildir.'),
  ('Bir aktörün yıllık film sayısı ile ABD\'de havuzda boğulma sayısı arasında on yıllık veride r = 0,67 korelasyon bulunmuştur. Bu bulgu en iyi nasıl yorumlanır?', 'Çok sayıda çift taranınca tesadüfi yüksek korelasyon kaçınılmazdır', ['Film çekimlerinin havuzlarda ölüm yarattığının kanıtıdır, çünkü r = 0,67 yüksektir', 'Havuzda boğulmaların film sayısını belirlediğinin kanıtıdır', 'Korelasyon katsayısı hesabının hatalı olduğunun kanıtıdır'], 'Yalnızca on yıllık bir veride ve milyonlarca olası çiftten seçilmiş bir ilişki, tesadüfen güçlü olabilir. Anlamlı bir mekanizma olmadan nedensellik yorumu yapılamaz.'),
  ('Bir çağrı merkezi, çalışanlarını ortalama görüşme süresi 3 dakikanın altında olanlara prim vererek ödüllendiriyor. Bu politikadan en olası istenmeyen sonuç hangisidir?', 'Sorun çözülmeden görüşmelerin kapatılması; memnuniyet düşer', ['Çalışan sayısının birden artması ve tüm aramaların aynı anda cevaplanması', 'Görüşme sürelerinin tamamen sabit kalması ve hiç değişmemesi', 'Müşterilerin hiçbir şikâyette bulunmaması ve memnuniyetin artması'], 'Süre ölçütü hedefe dönüşünce çalışanlar ölçütü iyileştirmenin kestirmesini bulur. Amaç (sorunu çözmek) değil, ölçüt (kısa görüşme) iyileşir.'),
  ('Bir yazılım şirketi geliştiricilerini yazdıkları kod satırı sayısına göre ödüllendiriyor. Bu ölçüt hakkında hangisi doğrudur?', 'Gereksiz uzun kod yazmayı teşvik eder', ['Kod kalitesini mükemmel biçimde yansıtır', 'Yalnızca küçük şirketler için yanıltıcıdır', 'Sadece satır sayısı azaldığında geçerlidir'], 'Kısa ve zarif kod, uzun ve şişirilmiş koddan çoğu zaman daha iyidir. Satır sayısı hedef olunca geliştiriciler satırı çoğaltarak ölçütü şişirir.'),
  ('A şehrinde bir yılda 500 trafik kazası, B şehrinde 100 trafik kazası kaydedildi. \'A şehri B şehrinden beş kat tehlikelidir\' sonucu için en önemli eksik bilgi hangisidir?', 'Nüfus ve araç sayısı', ['Kazaların yapıldığı günün saati', 'Şehirlerin deniz seviyesinden yükseklikleri', 'Kazaların ortalama hasar tutarının renkleri, ve bu sayı kayıtlara girer'], 'Mutlak sayılar, kentin büyüklüğüne bağlıdır; 100 bin kişi başına kaza ya da araç-km başına kaza gibi oranlar karşılaştırma için gerekir.'),
  ('Bir ilde grip sezonunda 1.200 kişi yoğun bakıma alınırken başka bir ilde 300 kişi alınıyor. İlkinde 6 milyon, ikincisinde 1 milyon kişi yaşıyor. Hangi ilde yoğun bakım oranı daha yüksektir?', 'İkinci ilde, 100 bin kişide 30\'a karşı ilkinde 20', ['İlk ilde, 100 bin kişide 20\'ye karşı ikincisinde 30', 'İki ilde eşittir', 'İlk ilde, çünkü sayı daha büyüktür'], 'İlk ilde 1200/6.000.000 = 100 binde 20, ikinci ilde 300/1.000.000 = 100 binde 30\'dur. Mutlak sayı büyük olan ilde oran daha küçüktür.'),
  ('Bir mevduat yıllık %10 faiz getiriyor ve aynı yıl enflasyon %6\'dır. Yıllık reel getiri yaklaşık kaçtır?', 'Yaklaşık %3,8', ['Tam olarak %4, çünkü fark doğrudan alınır', 'Yaklaşık %16', 'Yaklaşık %1,6'], 'Reel getiri (1,10 / 1,06) − 1 ≈ 0,0377\'dir. Nominal faizden enflasyonu doğrudan çıkarmak yaklaşık, ama tam olmayan bir sonuç verir.'),
  ('Bir şehirde 1990\'da 10 TL olan bir sepet, fiyat endeksi 1990\'da 100, 2020\'de 800 iken 2020 fiyatlarıyla kaç TL eder?', '80 TL', ['8 TL', '800 TL', '110 TL'], 'Endeks 8 katına çıkmıştır; 10 × 800 / 100 = 80 TL. Farklı yıllardaki parasal tutarlar ancak fiyat endeksiyle aynı yıla taşınarak karşılaştırılabilir.'),
  ('Bir fiyat endeksi 2010\'da 100, 2015\'te 125 ve 2020\'de 150\'dir. 2015\'ten 2020\'ye fiyat artışı yüzde kaçtır?', '%20', ['%25, çünkü iki oran toplanır', '%50', '%30'], '150 / 125 = 1,20; artış %20\'dir. 2010\'a göre %50 artış olması, her dönemin %25 olduğu anlamına gelmez; taban değiştikçe yüzde değişir.'),
  ('Bir hisse senedi endeksi 120 puandan 90 puana düşmüştür. Düşüş yüzde kaçtır?', '%25', ['%30', '%33,3', '%20'], 'Düşüş 30 puandır ve taban 120 olduğundan 30 / 120 = %25\'tir. Aynı endekse tekrar %25 artış gerekse yine eski değere dönülemezdi; gereken artış %33,3\'tür.'),
  ('Bir kamu projesine 2 milyar liralık bütçe ayrılmıştır. Günde 1 milyon lira harcanırsa bu bütçe yaklaşık kaç yıl yeter?', 'Yaklaşık 5,5 yıl', ['Yaklaşık 2 yıl, çünkü bütçe iki milyar liradır', 'Yaklaşık 55 yıl', 'Yaklaşık 200 yıl'], '2.000.000.000 / 1.000.000 = 2000 gündür; 2000 / 365 ≈ 5,5 yıl. Büyük bütçeler zaman ya da kişi başına bölünerek anlamlandırılabilir.'),
  ('Bir gölde bir nilüfer yaprağı her gün iki katına çıkarak çoğalıyor ve göl 48. günde tamamen kaplanıyor. Gölün yarısı kaçıncı günde kaplanmıştır?', '47. gün', ['24. gün, çünkü yarısı tam ortadadır', '40. gün', '36. gün'], 'Her gün alan ikiye katlandığı için gölün tamamı kaplanmadan bir gün önce yarısı kaplıdır. Üstel büyüme, sezgisel olarak \'yavaş başlayıp birden dolan\' bir süreçtir.'),
  ('Yıllık %6 büyüyen bir değerin yaklaşık kaç yılda iki katına çıkacağını 72 kuralı ile tahmin ediniz.', 'Yaklaşık 12 yıl', ['Yaklaşık 6 yıl, çünkü büyüme yüzdesi yıla eşittir', 'Yaklaşık 18 yıl', 'Yaklaşık 36 yıl'], '72 kuralına göre ikiye katlanma süresi 72 / büyüme yüzdesi = 72 / 6 = 12 yıldır; tam hesap yaklaşık 11,9 yıl verir.'),
  ('Bir salgında vaka sayısı her 3 günde iki katına çıkıyor. 30 gün sonra vaka sayısı başlangıcın kaç katı olur?', '1024 katı', ['30 katı, çünkü artış doğrusaldır', '300 katı', '10 katı'], '30 günde 10 katlanma olur; 2^10 = 1024. Doğrusal düşünmek (günde bir kez 3 vaka eklemek) üstel büyümeyi büyük ölçüde küçümser.'),
  ('Bir araştırmacı, boy ölçümleri 1 cm duyarlılığında yapıldığı hâlde ortalama boyu \'172,38462 cm\' olarak raporluyor. Bu rapor için en uygun eleştiri nedir?', 'Ölçüm duyarlılığının ötesindeki basamaklar sahte kesinlik izlenimi verir', ['Ortalama boyun hiçbir zaman ondalıklı olamayacağı, çünkü boy hep tam sayıdır', 'Santimetrenin istatistikte kullanılamayacağı', 'Ortalamaların her zaman tam sayıya yuvarlanması gerektiği'], 'Bir sonucun bildirilen basamağı, verinin kesinliğini aşmamalıdır. Aşırı hassas rakamlar sonucun gerçekte olduğundan daha kesin olduğu izlenimini verir.'),
  ('Bir haber başlığı \'Düzenli kahve içenler daha uzun yaşıyor\' diyor; çalışma, 40.000 kişiyi gözlemleyip kahve alışkanlıklarını anketle sormuş ve kimseye müdahale etmemiştir. Bu başlık için hangi yorum en doğrusudur?', 'Gözlemsel ilişki bildirilmiştir; nedensellik kanıtlanmamıştır', ['Büyük örneklem nedenselliği kanıtlar; kahve uzun yaşam sağlar', 'Kahve içmeyen kimsenin uzun yaşayamayacağını gösterir', 'Çalışmanın anket kullanması nedeniyle hiçbir bulgu içermediğini gösterir'], 'Yalnızca gözlenen gruplar karşılaştırıldığı için sağlık davranışları ve yaşam tarzı gibi karıştırıcılar dışlanamaz. Büyük örneklem karıştırıcıyı ortadan kaldırmaz, yalnızca tahmini kesinleştirir.'),
  ('Kanıt hiyerarşisinde, nedensellik konusunda genellikle en güçlü kanıt düzeyi hangisidir?', 'Rastgele kontrollü çalışmaların sistematik derlemesi', ['Tek bir uzman görüşü ve anlatılan vaka örnekleri', 'Yalnız bir hasta grubunu anlatan vaka serisi çalışması', 'Hayvanlar üzerinde yürütülen tek bir laboratuvar deneyi'], 'Rastgele atama karıştırıcıları dengeler; birden çok çalışmanın sistematik birleştirilmesi tek çalışmanın şansa bağlı sapmasını da azaltır. Uzman görüşü ve anekdot en zayıf düzeydedir.'),
  ('Farelerde güçlü bir etki gösteren bir ilacın insanlarda aynı etkiyi göstermesi neden garanti değildir?', 'Tür farkı nedeniyle insanlara genellenebilirlik sınırlıdır', ['Farelerde yapılan deneylerde hiç ölçüm yapılamaması', 'İlaç etkisinin yalnızca laboratuvar sıcaklığına bağlı olması', 'İnsan çalışmalarının her zaman daha küçük örneklem içermesi'], 'Fizyoloji, doz ve metabolizma türler arasında farklıdır; kontrollü koşullardaki bulgu başka bir türde değişebilir. Bu nedenle hayvan çalışmaları ancak ön kanıt sayılır.'),
  ('Bir okulda öğrencilerin okuma becerisi, yeni bir program uygulanmadan önce ve bir yıl sonra ölçülüyor ve ortalama puan yükseliyor. Programın etkili olduğunu iddia etmek neden yetersizdir?', 'Kontrol grubu olmadığından etki nedeni bilinemez', ['Önceki ölçüm yapıldığı için sonraki ölçüm anlamsızdır', 'Okuma becerisi sayısal olarak hiçbir zaman ölçülemez', 'Bir yıl çok kısa bir süredir ve hiçbir ilerleme göstermez'], 'Öğrenciler zaten bir yılda gelişirdi. Benzer ama programı almayan bir karşılaştırma grubu, zamanın doğal etkisinin ayrıştırılması için gereklidir.'),
  ('Bir tedavi çalışmasında hem hastalar hem değerlendiren doktorlar hangi grupta olunduğunu bilmiyorsa çalışma için ne denir ve bu ne sağlar?', 'Çift kör; hem katılımcı hem değerlendirici beklentisi azalır', ['Tek kör; yalnızca katılımcının beklentisini ortadan kaldırır', 'Açık etiketli; beklenti etkilerini artırır', 'Rastgele olmayan; gruplardaki karıştırıcıları ortadan kaldırır'], 'Çift körlemede ne hasta ne değerlendirici atamayı bilir; bu nedenle beklenti ve ölçüm yanlılığı azalır. Rastgeleleştirme ise gruplar arası dengeyi sağlar.'),
  ('Bir kentte \'yüzyılın taşkını\' haberinden birkaç yıl sonra aynı büyüklükte ikinci bir taşkın yaşanıyor ve insanlar istatistiklerin yanlış olduğunu söylüyor. Bu tepkinin hatası nedir?', '\'Yüzyılda bir\' ifadesi her yıl %1 olasılık demektir; ardışık olayları dışlamaz', ['Taşkınların yalnızca yüzyılda bir kez gerçekleşebilmesi ve hiç tekrarlanamaması', 'Olasılık hesaplarının doğa olaylarına hiçbir zaman uygulanamaması', 'Yüzyıllık verinin sayıya dökülememesi nedeniyle hesabın geçersizliği'], 'Dönüş süresi, olayın ortalama sıklığını anlatır; olaylar düzenli aralıklarla gelmez. Yüzyılda bir olay, art arda iki yıl içinde de görülebilir.'),
  ('Bir hava tahmincisi \'yağış ihtimali %70\' dediği yüzlerce gün için kayıt tutuyor. Tahminleri iyi kalibre ise bu günlerin yaklaşık yüzde kaçında yağış gözlenmesi beklenir?', 'Yaklaşık %70', ['Yaklaşık %100', 'Yaklaşık %50', 'Yaklaşık %30'], 'Kalibrasyon, bildirilen olasılıkla gerçekleşme sıklığının örtüşmesidir. Yani %70 denilen günlerin yaklaşık %70\'inde, %30\'unda yağış olmaması beklenir.'),
  ('Bir tahminci \'yarın yağmur yağma olasılığı %10\' diyor ve ertesi gün yağmur yağıyor. Bu tek olay tahmincinin yanlış olduğunu kanıtlar mı?', 'Hayır; %10 olasılıklı olaylar da zaman zaman gerçekleşir', ['Evet; tahmin gerçekleşmediği için tamamen hatalıdır, çünkü olasılık hep kesindir', 'Evet; çünkü %10, yağmurun asla yağmayacağını bildirir', 'Hayır; çünkü olasılık tahminleri hiçbir zaman sınanamaz'], 'Olasılıksal tahminler tek bir olaydan değil, çok sayıda tahminin kalibrasyonundan değerlendirilir. Düşük olasılık, olayın imkânsız olduğu anlamına gelmez.'),
  ('\'Neredeyse kesin\', \'olası\', \'ihtimal dahilinde\' gibi sözel olasılık ifadelerinin raporlarda tek başına kullanılması hangi soruna yol açar?', 'Farklı okuyucular aynı ifadeye çok farklı sayılar karşılık getirebilir', ['Okuyucuların ifadeleri hiç anlamaması ve yalnızca sayıları tercih etmesi', 'Sözel ifadelerin sayısal ifadelerden her zaman daha kesin olması', 'Sözel ifadelerin yalnızca bilimsel dergilerde yasak olması'], 'Aynı \'olası\' ifadesi biri için %55, başkası için %85 olabilir. Sayısal aralıklarla birlikte verilen ifadeler yanlış anlaşılmayı azaltır.'),
  ('A hastanesi 10 ameliyatın %90\'ında, B hastanesi 90 ameliyatın %50\'sinde başarılı olmuştur. İki hastanenin birleşik başarı oranı yüzde kaçtır?', '%54', ['%70, çünkü iki oran doğrudan ortalanır', '%60', '%45'], 'Başarılı ameliyat sayısı 9 + 45 = 54, toplam 100\'dür; oran %54\'tür. Oranların aritmetik ortalaması (%70), grup büyüklükleri farklıyken yanıltır.'),
  ('Bir kentte \'hırsızlık\' suçunun tanımı genişletilip önceden \'kayıp\' sayılan olaylar da hırsızlığa dahil ediliyor. Ertesi yıl hırsızlık sayısı %30 artıyor. Bu artış için en uygun değerlendirme hangisidir?', 'Bir bölümü, tanımın genişlemesinden kaynaklanabilir', ['Artış mutlaka gerçek bir suç dalgasını gösterir', 'Artış tanımla ilgisizdir ve yalnız nüfus artışına bağlıdır', 'Artış, polislerin kayıt tutmamasının kanıtıdır'], 'Sayılan olayın kapsamı genişleyince, gerçek davranış değişmese de kayıtlar artar. Zaman içindeki karşılaştırmalarda tanımın sabit olması gerekir.'),
  ('Bir şehirde polis, tek bir mahallede devriyeleri artırıyor ve o mahallede yazılan trafik cezası sayısı iki katına çıkıyor. \'Bu mahallede sürücüler iki kat ihlal yapıyor\' sonucu neden temkinle karşılanmalıdır?', 'Daha çok bakılan yerde daha çok olay bulunur', ['Cezaların hiçbir zaman ihlali yansıtmaması', 'Mahalle sakinlerinin tamamen hatasız sürmesi', 'Devriye sayısının ceza sayısıyla ilgisiz olması'], 'Gözlem yoğunluğu arttıkça saptanan olay sayısı da artar. Gerçek ihlal oranını ölçmek için denetim yoğunluğu sabit tutulmalıdır.'),
  ('Bir infografik, \'Gençlerin %70\'i bu uygulamayı kullanıyor\' diyor; kaynak, örneklem büyüklüğü ve ölçüm yöntemi belirtilmiyor. Okuyucunun ilk yapması gereken doğru adım hangisidir?', 'Verinin kaynağını ve yöntemini araştırmak', ['Sayıyı doğru kabul edip başkalarına iletmek', 'Yüzdeyi kendi çevresindeki gençlerle karşılaştırmak', 'Grafiğin renklerinin güzelliğine bakarak güvenmek'], 'Kaynağı ve yöntemi bilinmeyen bir sayı, güvenilirliği değerlendirilemeyen bir iddiadır. Örneklem, soru ifadesi ve tarih bilgisi olmadan yüzde anlamsız kalabilir.'),
  ('Bir haber, \'Ankete katılanların %70\'i\' ifadesini kullanıyor ancak ankete kimlerin, kaç kişinin, nasıl katıldığını belirtmiyor. Bu eksiklikte hangisi doğrudur?', 'Yüzdenin paydası bilinmediği için değerlendirilemez', ['Yüzde sayısı tek başına yeterli kanıttır', 'Anketin kapsamı kamuya açık olmadığı için kanıt değerlidir', 'Yüzde yerine sayı verilseydi sorun hiç çözülmezdi'], 'Örneklem büyüklüğü, seçim yöntemi ve soru metni olmadan bir yüzdeyi değerlendirmek mümkün değildir. Şeffaf raporlama, güvenilir veri iletişiminin temelidir.'),
  ('Bir istatistik kurumu, küçük ilçeler için yayımladığı bazı tablo hücrelerinde 1 ya da 2 gibi çok küçük sayıları gizliyor. Bu uygulamanın başlıca amacı nedir?', 'Dolaylı kimliklendirmeyi engellemek', ['Tablonun daha geniş görünmesini sağlamak', 'Sayıların toplamını her zaman yuvarlamak', 'Verinin yanlış olduğunu saklamak'], 'Birkaç kişilik hücrelerde, örneğin \'bu mahallede tek bir 90 yaş üstü kişi\' gibi bilgilerle kimlik açığa çıkabilir. Küçük hücre bastırma bu riski azaltır.'),
  ('Bir şirket \'Çalışanlarımızın ortalama maaşı 85.000 TL\' diyor; sendika ise \'Çalışanların yarısı 40.000 TL\'nin altında kazanıyor\' diyor. Her iki ifade de doğruysa aralarındaki fark en iyi nasıl açıklanır?', 'Birkaç çok yüksek maaş ortalamayı yukarı çekiyor', ['İki ifadeden biri kesin olarak yanlıştır', 'Ortalama ve medyan her zaman aynı olduğundan çelişki yoktur', 'Sendikanın medyanı yanlış hesaplamış olması gerekir'], 'Sağa çarpık maaş dağılımında ortalama medyandan çok büyüktür. Taraflar, kendi görüşlerine uygun ölçüyü seçebilir; seçici ölçü kullanımına dikkat edilmelidir.'),
  ('Bir ülke \'toplam enerji tüketimimiz dünyanın en yüksekleri arasında\' derken başka biri \'kişi başı tüketimimiz ortalamanın altında\' diyor. Her ikisi doğruysa en olası açıklama nedir?', 'Nüfus fazladır; kişi başına pay düşüktür', ['İki ifadeden biri kesinlikle yanlış hesaplanmıştır', 'Kişi başı hesap ancak ülke küçükse yapılabilir', 'Toplam tüketim hiçbir zaman nüfusa bağlı değildir'], 'Toplam, ülkenin büyüklüğüne; kişi başına değer ise bireysel tüketime bağlıdır. Her iki ölçü de doğru ama farklı sorulara yanıt verir.'),
  ('Doğrudan yaş standardizasyonunda iki toplumun ölüm oranları karşılaştırılırken hangi adım uygulanır?', 'Yaş özgü oranlar ortak standart nüfusa uygulanır', ['İki toplumun toplam ölüm sayıları doğrudan bölünür', 'İki toplumun ortalama yaşları birbirinden çıkarılır', 'İki toplumun en yaşlı grubu çıkarılır ve geri kalan karşılaştırılır'], 'Aynı standart yaş yapısına uygulandığında, yaş dağılımı farkı karşılaştırmadan ayıklanır. Böylece oran farkları yaş yapısının değil, gerçek risk farklarının yansıması olur.'),
  ('Bir araştırmacı, 25 yaşındakilerle 65 yaşındakileri aynı yıl karşılaştırıp 65 yaşındakilerin daha az eğitimli olduğunu buluyor ve \'insanlar yaşlandıkça eğitim düzeyini kaybeder\' diyor. Bu sonuçtaki hata nedir?', 'Kohort etkisi yok sayılıyor', ['Eğitim düzeyinin sayısal olarak ölçülememesi', '65 yaşındakilerin sayıca fazla olması', 'Eğitim düzeyinin yaşla her zaman arttığı'], 'Yaşlılar gençken daha az kişi uzun süre okuyabiliyordu. Kesit farkı, aynı kişilerin zamanla değişmesinden değil, kuşakların farklı koşullarından kaynaklanır.'),
  ('Bir zekâ ölçeği, aynı kişilere iki hafta arayla uygulandığında kişilerin puanlarını belirgin biçimde değiştiriyor. Bu ölçeğin hangi özelliği düşüktür?', 'Güvenirlik', ['Geçerlilik; ölçeğin sayısal olması', 'Temsil gücü; kişi sayısının az olması', 'Çarpıklık; dağılımın simetrik olmaması'], 'Aynı kişide aynı özelliği ölçen iki uygulamanın birbirinden farklı çıkması düşük tutarlılığın işaretidir. Güvenilmeyen bir ölçüt geçerli de olamaz.'),
  ('Bir anketle gelirler sorulduğunda katılımcıların bir bölümü gerçek gelirlerini küçük ya da büyük göstermektedir. Bu tür ölçümlerde karşılaşılan sorun için en doğru ifade hangisidir?', 'Beyanlar sistematik sapma taşıyabilir', ['Anketler hiçbir zaman ölçüm yapamaz, çünkü anket kullanılmıştır', 'Beyanların her zaman tam doğru olması', 'Gelir sorularının yasak olması'], 'Utanma, çekinme ve hatırlama hataları nedeniyle beyanlar gerçek değerlerden sapar. Mümkünse kayıtlı verilerle karşılaştırmak ölçümün geçerliliğini artırır.'),
  ('Bir lig tablosunda 1. ve 2. takım arasında 0,1 puanlık, 2. ve 3. takım arasında 20 puanlık fark bulunuyor. Sıralamaya bakarak yapılacak en uygun yorum hangisidir?', 'Sıra, aralarındaki fark büyüklüğünü göstermez', ['Her sıra arasındaki fark eşittir', '1. takım diğerlerinden kesinlikle çok üstündür', 'Sıralama puanların farkından daha değerlidir'], 'Sıra yalnızca sıralama bilgisi taşır, aralıkları taşımaz. 0,1 puanlık fark ölçüm belirsizliği içinde kalabilir; 20 puanlık fark ise belirgindir.'),
  ('Bir araştırmacı, bir sosyal medya platformundaki milyonlarca paylaşımı analiz edip \'bütün ülkenin görüşü\' diye sunuyor. Bu çıkarımın temel sorunu nedir?', 'Kullanıcılar ülkenin rastgele örneği değildir', ['Paylaşım sayısının fazla olmasının hesaplamayı imkânsızlaştırması', 'Sosyal medyada kimsenin görüşünü paylaşmaması', 'Yüzdelerin sosyal medyada hesaplanamaması'], 'Milyonlarca gözlem, kimlerin kullandığı sorusunu yanıtlamaz. Seçilim yanlılığı, örneklem büyüdükçe kaybolmaz; yalnız tahmin daha \'kesin ama yanlış\' hâle gelir.'),
  ('Bir kişi gece sokak lambasının altında anahtarını arıyor; anahtarı başka bir yerde düşürdüğünü ama \'burada ışık var\' dediğini söylüyor. Bu anekdot, veri analizinde hangi eğilime benzetilir?', 'Yalnızca ölçülebilir olana bakmaya', ['Büyük sayılar yasasını uygulamaya', 'Ortalamaya dönüşü yanlış yorumlamaya', 'Çoklu karşılaştırma düzeltmesi yapmaya'], 'Sokak lambası etkisi, ölçülebilir olanın önemli olanla karıştırılmasıdır. Veri bulunan yerde araştırmak, sorunun gerçekte nerede olduğunu gizleyebilir.'),
  ('Bir haberde \'Başvuru sayısı bir yılda %200 arttı\' ifadesi geçiyor. Önceki yıl 50 olan başvuru sayısı bu yıl kaç olmuştur?', '150', ['100', '200', '250'], '%200 artış, ilk değerin iki katı kadar eklenmesidir: 50 + 2 × 50 = 150, yani 3 katıdır. \'Üç kat\' ile \'%300 artış\' ise aynı anlama gelmez.'),
  ('Bir parti oy oranı %8\'den %6\'ya düşmüştür. Bu düşüş hangi iki biçimde doğru anlatılabilir?', '2 yüzde puanlık düşüş; göreli %25', ['2 yüzde puanlık düşüş, yani göreli olarak %2\'lik düşüş', '%25 puanlık düşüş, yani göreli olarak 2\'lik düşüş', '6 yüzde puanlık düşüş, yani göreli olarak %75\'lik düşüş'], 'Mutlak fark 8 − 6 = 2 yüzde puandır; göreli fark 2 / 8 = %25\'tir. Yüzde puan ile yüzde farkı karıştırmak abartılı ya da yetersiz haberlere yol açar.'),
  ('Bir şehirde nüfusun %0,1\'i belirli bir hastalığa yakalanıyor ve şehirde 8 milyon kişi yaşıyor. Hasta sayısı yaklaşık kaçtır?', '8.000 kişi', ['800 kişi', '80.000 kişi', '8 kişi'], '8.000.000 × 0,001 = 8.000\'dir. Küçük yüzdeler büyük nüfuslarda büyük mutlak sayılara karşılık gelir.'),
  ('Bir üretim hattında kusur olasılığı \'on binde 2\' olarak bildiriliyor. Bu oran yüzde olarak ifade edilirse nedir?', '%0,02', ['%2', '%0,2', '%0,002'], 'On binde 2 = 2 / 10.000 = 0,0002 = %0,02\'dir. Binde, on binde ve yüzde karşılaştırmalarında ondalık kaymalara dikkat etmek gerekir.'),
  ('Bir sınavda \'sizin yüzdeliğiniz 80\' denmesi ile \'sınavdan %80 aldınız\' denmesi arasındaki fark nedir?', 'Yüzdelik, %80\'inin geride kaldığını gösterir', ['İkisi aynı anlama gelir', 'Yüzdelik, soruların %80\'inin doğru yapıldığını gösterir', 'Yüzde puan, adayların %80\'ini geride bıraktığını gösterir'], 'Yüzdelik, bir kişinin diğerlerine göre konumunu anlatan göreli bir ölçüdür. Yüzde ise ham performansın bir oranıdır; birbirinin yerine kullanılamaz.'),
  ('1999\'da NASA\'nın Mars İklim Gözlemcisi uzay aracı, bir ekibin kuvvet itkisini pound-saniye, diğerinin Newton-saniye cinsinden vermesi nedeniyle kayboldu. Bu olay veri okuryazarlığı için hangi dersi verir?', 'Birimler doğrulanmazsa veriler yanlış birleşir', ['Newton-saniye biriminin hiçbir zaman kullanılamayacağı', 'Hesapların yalnızca elle yapılması gerektiği', 'Uzay araçlarının sayısal veriyle yönetilemeyeceği'], 'Aynı sayı farklı birimlerde farklı büyüklüğe karşılık gelir. Veri kümelerini birleştirmeden önce birim, ölçek ve tanım uyumu kontrol edilmelidir.'),
  ('Olaylar gerçekleştikten sonra insanların \'Zaten biliyordum\' demesi ve önceki tahminlerini sonuca yaklaştırarak hatırlaması hangi eğilimle ilgilidir?', 'Sonradan bilme yanlılığı', ['Çıpalama, yani ilk sayıya yakın tahmin etmek', 'Mevcudiyet sezgisi', 'Kayıptan kaçınma'], 'Fischhoff\'un 1975 çalışması, sonuç bilindikten sonra insanların olayı daha öngörülebilir buldukları ve önceki tahminlerini yanlış hatırladıklarını gösterdi. Bu, geçmiş kararların adil değerlendirilmesini zorlaştırır.'),
  ('\'Bu bitkisel ürünün işe yaradığını kanıtlayan hiçbir çalışma yok; o hâlde ürün kesinlikle işe yaramaz.\' Bu çıkarım hangi yanılgıdır?', 'Kanıt yokluğunu yokluğun kanıtı saymak', ['Hayatta kalma yanlılığı, çünkü yalnız başarılılar gösterilir', 'Kumarbaz yanılgısı, çünkü olaylar birbirini etkiler', 'Savcı yanılgısı, çünkü koşullu olasılıklar ters çevrilir'], 'Çalışmanın yapılmamış ya da yetersiz olması, etkisizliğin kanıtı değildir. Etkisizliği göstermek için yeterli güçte iyi tasarlanmış çalışmalar gerekir.'),
  ('Bir sosyal medya paylaşımı \'Milyonlarca kişi bu ürünü kullanıyor, o hâlde etkilidir\' diyor. Bu argümanın zayıflığı nedir?', 'Popülerlik etkililik kanıtı değildir', ['Milyonlarca kişinin hiçbir zaman ankete katılmaması', 'Kullanıcı sayısının hiç sayılmaması', 'Etkili ürünlerin hiçbir zaman popüler olamaması'], 'Bir şeyin çok kişi tarafından kullanılması etkililik hakkında kanıt sağlamaz; yanılgılar da yaygınlaşabilir. Etkililik, kontrollü karşılaştırmalarla ölçülür.'),
  ('Bir kişi, \'Aşı yüzde yüz koruma sağlamıyor, öyleyse hiçbir işe yaramıyor\' diyor. Bu mantık hangi hataya örnektir?', 'Nirvana yanılgısı', ['Hayatta kalma yanlılığı', 'Çoklu karşılaştırma', 'Savcı yanılgısı'], '%100\'den düşük bir etkililik, riskin yine de büyük ölçüde azaldığı anlamına gelebilir. Kararlar, mükemmel olmayan seçeneklerin birbirine göre iyiliğine dayanmalıdır.'),
  ('Bir tahminci, bir hisse senedinin yükseleceğini söyleyen 20 farklı gerekçe sunuyor, yükseleceğini gösteren her veriyi seçiyor ve düşeceğini gösteren verileri anmıyor. Bu stratejinin adı nedir?', 'Kiraz toplama', ['Rastgele örnekleme', 'Kör çözümleme', 'Çapraz doğrulama'], 'Yalnızca tezi destekleyen veriler öne çıkarılırsa, kanıt toplamı çarpıtılır. Dengeli bir değerlendirme, hem lehte hem aleyhte kanıtı sunar.'),
  ('Bir haber, henüz hakem değerlendirmesinden geçmemiş bir ön baskı (preprint) çalışmasına dayanarak kesin sonuçlar duyuruyor. Okuyucunun bu durumda nasıl davranması uygundur?', 'Geçici bulgu olarak görüp doğrulama beklemek', ['Sonuçları hakem onayı almış kadar kesin kabul etmek', 'Ön baskı çalışmalarının her zaman yanlış olduğunu varsaymak', 'Sonucu yalnızca başlığa bakarak yorumlamak'], 'Ön baskılar, bağımsız hakem incelemesinden önceki çalışmalardır ve hata içerebilir. Bunlar değerli olabilir, ancak bulgular doğrulanana dek temkinle yorumlanmalıdır.'),
  ('Bir başlık \'Önemli bir fark bulundu\' diyor. Haber metninde \'önemli\' sözcüğünün istatistiksel anlamlılık mı, yoksa gündelik anlamda büyük ve önemli bir fark mı kastettiği belirtilmiyor. Sorun nedir?', 'Anlamlı fark küçük olabilir', ['\'Önemli\' sözcüğü istatistikte hiçbir zaman kullanılmaz', 'İstatistiksel anlamlılık her zaman büyük fark demektir', 'Haber başlıklarının doğru olması her zaman garanti edilir'], 'Bilimsel metinde \'anlamlı\' şansla açıklanamayacak bir fark anlamına gelir, etkinin büyüklüğünü söylemez. Okuyucu için ayrımın açıkça belirtilmesi gerekir.'),
  ('Bir şehirde \'bu yıl ölüm sayısı rekor kırdı\' haberi çıkıyor. Şehir nüfusu son 20 yılda iki katına çıkmıştır. Bu haber için en uygun yorum hangisidir?', 'Mutlak sayı nüfusla artar; oran incelenmeli', ['Rekor sayı, kentin her zaman daha tehlikeli olduğunu gösterir', 'Nüfus artışı ölüm sayısını hiç etkilemez', 'Ölüm oranları hiçbir zaman hesaplanamaz'], 'Nüfus büyüdükçe mutlak sayılar doğal olarak yükselir; karşılaştırma için oranlar kullanılmalıdır. Bu nedenle \'rekor\' haberleri büyüklük etkisiyle karışabilir.'),
  ('Bir araştırma sonucu, \'Çocuklarda ekran süresi arttıkça not ortalaması düşüyor\' diye haberleşiyor. Çalışma, 120 çocuğun ailelerinden alınan anket yanıtlarına dayanıyor. Haberi değerlendirmek için ilk sorulması gereken soru hangisidir?', 'Çalışma nasıl yapıldı?', ['Haberi hangi gazete yazdı?', 'Başlık kaç kelimeden oluşuyor?', 'Çocukların kaç tanesi televizyonu seviyor?'], 'Örneklem, ölçüm yöntemi ve karıştırıcı kontrolü bulgunun güvenilirliğini belirler. Aile geliri gibi etkenler hem ekran süresini hem notu etkileyebilir.'),
  ('Bir reklam \'Diş hekimlerinin %80\'i önerir\' diyor. Reklamın dipnotunda, hekimlerin birden fazla marka seçebildiği anlaşılıyor. Bu durum, reklamın iddiasını nasıl etkiler?', 'Birden çok marka önerilebildiğinden iddia şişkindir', ['İddia kesinlikle doğrudur ve marka tek başına önerilmiştir', 'İddia, hekimlerin başka bir markayı önermediğini kanıtlar', 'Reklamlarda yüzdeler hiçbir zaman kullanılmaz'], 'Çoklu seçim izin verildiğinde yüzde, \'tek seçenek\' değil \'seçeneklerden biri\' anlamına gelir. Ölçüm biçimini bilmeden yüzdeyi yorumlamak yanıltıcıdır.'),
  ('Bir ankette çoktan seçmeli bir soruda katılımcılar birden fazla seçeneği işaretleyebiliyor ve seçeneklerin yüzdeleri toplamı %140 çıkıyor. Bu durum için doğru yorum hangisidir?', 'Sorun yok; toplam %100\'ü aşabilir', ['Hesap hatası vardır ve veri geçersizdir', 'Anketin hiçbir sorusu doğru yanıtlanmamıştır', 'Katılımcıların yarısı rastgele cevap vermiştir'], 'Her yüzde, katılımcıların o seçeneği işaretleme oranını gösterir ve katılımcılar birden çok seçenek seçebildiğinden toplam 100\'ü geçebilir. Tek yanıtlı sorularda toplam 100 olmalıdır.'),
  ('Bir spor takımı, son 5 maçta 4 galibiyet almış ve teknik direktör \'formumuzun zirvesindeyiz, bundan sonra da kazanırız\' diyor. Bu çıkarım için hangi değerlendirme en uygundur?', 'Beş maç küçük örneklemdir', ['Beş maç, bir takımın gücünü kesin biçimde ölçer', 'Galibiyet serileri her zaman devam eder', 'Rakiplerin gücü sonuçlarla hiç ilgili değildir'], 'Küçük örneklemlerde oranlar şansla büyük dalgalanır. Uzun dönemli performans ve rakip gücü dikkate alınmadan seri sonuçlardan eğilim çıkarılamaz.'),
  ('Bir şehirde, hava durumu haberlerinde \'bu yaz son 100 yılın en sıcak yazı\' denmesine rağmen bir kişi \'ben bu yaz her zamankinden daha serin hissettim\' diyor. Bu kişinin kişisel gözlemi, ortalama sıcaklık verisiyle çelişirse neden veri tercih edilmelidir?', 'Kişisel gözlem sınırlı bir örneklemdir', ['Kişisel gözlem hiçbir zaman gerçeği yansıtmaz', 'Sıcaklık verisi hiçbir zaman ölçülemez', 'Rekorlar yalnızca duyguya dayanır'], 'Tek bir kişinin deneyimi sınırlı zaman ve mekânı kapsar; sistematik ölçüm ise kapsamlı ve karşılaştırılabilir kayıtlar sunar. Anekdot ve veri çeliştiğinde, ölçüm yöntemi değerlendirilerek veri ağırlıklandırılır.'),
  ('Bir ülkede servet dağılımı Pareto benzeri kalın kuyruklu bir yapıdadır. \'Ortalama servet\' hesaplandığında bu ortalama için hangisi geçerlidir?', 'Birkaç çok zengin tarafından yukarı çekilir; tipik kişi medyana yakındır', ['Tipik kişinin servetine çok yakındır; çünkü ortalama her zaman tipiktir', 'Medyandan her zaman küçüktür; çünkü zenginler azdır', 'Zenginlerin sayısından bağımsızdır; çünkü servet ölçülemez'], 'Kalın kuyruklu dağılımlarda küçük bir azınlık toplamın büyük bölümüne sahiptir ve ortalamayı yukarı çeker. Medyan, tipik durumu daha iyi yansıtır.'),
  ('Bir barda 10 kişi oturuyor ve ortalama servetleri 100 bin liradır. Dünyanın en zengin kişilerinden biri içeri girince \'bardaki ortalama servet\' milyarlara çıkıyor. Bu durumda medyan servet nasıl değişir?', 'Çok az değişir', ['Aynı ölçüde milyarlara çıkar', 'Sıfıra düşer', 'Yarıya iner'], 'Medyan sıralamaya dayandığı için tek bir uç gözlem onu belirgin biçimde değiştirmez. Ortalama ise uç değerlerden doğrudan etkilenir.'),
  ('Bir araştırmacı, bir şehrin bütün bireylerin gelirini topladığında toplamın %50\'sinin en zengin %1\'e ait olduğunu görüyor. Bu durum için doğru çıkarım hangisidir?', 'Çok çarpıktır; ortalama tipik kişiyi anlatmaz', ['Gelir dağılımı eşittir; çünkü toplam gelir sabittir', 'Ortalama gelir her zaman tipik kişiyi yansıtır', 'En zengin %1\'in varlığı ortalamayı etkilemez'], 'Yüksek yoğunlaşma, ortalamayı küçük bir azınlığın belirlediği anlamına gelir. Eşitsizlik göstergeleri ve medyan, tek başına ortalamadan daha anlamlıdır.'),
  ('Bir kişi \'1 milyon liralık proje çok pahalı\' diyor. Proje yılda 10 milyar liralık bütçeli bir kuruma ait ve 40 milyon kişiye hizmet ediyor. Bu sayıyı değerlendirirken en yararlı yaklaşım hangisidir?', 'Sayıyı bağlam içinde oranlamak', ['Sayıyı tek başına büyük kabul etmek', 'Sayıyı yalnızca dolar cinsine çevirmek', 'Sayıyı hiç yorumlamamak'], '1 milyon lira bütçenin onbinde 1\'i, kişi başına yaklaşık 2,5 kuruştur. Büyük görünen mutlak sayılar, bağlam içinde küçük olabilir.'),
  ('Bir haber, \'Şirket yılda 100 milyon liralık zarar etti\' diyor. Şirketin ciro hacmi 50 milyar lira ise bu zararın ciroya oranı yaklaşık kaçtır?', 'Yaklaşık %0,2', ['Yaklaşık %2', 'Yaklaşık %20', 'Yaklaşık %0,02'], '100 milyon / 50 milyar = 0,002 = %0,2\'dir. Mutlak zarar büyük görünse de ciroya oranla küçüktür.'),
  ('Ülke borcu 5 trilyon liradır ve 50 milyon vatandaş vardır. Borç eşit paylaştırılsaydı kişi başına yaklaşık ne kadar düşerdi?', '100 bin lira', ['10 bin lira', '1 milyon lira', '10 milyon lira'], '5 × 10^12 / 5 × 10^7 = 10^5 = 100.000 liradır. Büyük sayıları kişi başına bölmek, ölçeği anlamlandırmaya yardımcı olur.'),
  ('Bir şehirde nüfus yıllık %5 artarken trafik kaza sayısı %5 artıyor. Kaza sayısındaki artış için hangi yorum en doğrudur?', 'Kişi başına oran değişmemiştir', ['Kişi başına kaza oranı da %5 artmıştır', 'Kişi başına kaza oranı %5 azalmıştır', 'Kaza oranı hesaplanamaz hâle gelmiştir'], 'Pay ve payda aynı oranda arttığından oran sabit kalır. Mutlak sayı artışı, risk artışı anlamına gelmez.'),
  ('Bir teori, hangi sonuç çıkarsa çıksın \'bu da teoriyi doğruluyor\' diyerek her gözlemi açıklayabiliyor. Karl Popper\'ın yanlışlanabilirlik ölçütüne göre bu teori hakkında ne söylenebilir?', 'Hiçbir gözlemle çürütülemediğinden bilimsel sayılmaz', ['Her sonuçla uyumlu olduğundan en güçlü teoridir', 'Bilimsel sayılır, çünkü çok sayıda örnekle desteklenmiştir', 'Doğruluğu sınanamayacağı için kesinlikle yanlıştır'], 'Bilimsel iddia, belirli sonuçları dışlayıp çürütülebilir olmalıdır. Her sonuca uyum sağlayan açıklama, hiçbir şey öngörmez.'),
  ('Hakem değerlendirmesinden geçmiş bir makale yayımlanıyor. Bu durum, makalenin sonucu hakkında hangi çıkarıma izin verir?', 'Yöntem incelenmiştir, doğruluk kesin garanti değildir', ['Bulgular kesin ve kalıcı biçimde doğrulanmıştır', 'Hakem değerlendirmesi hiçbir inceleme içermez', 'Makale artık yeniden üretilmeye ihtiyaç duymaz'], 'Hakemlik hataları ve yanlılıkları azaltır ama ortadan kaldırmaz; hakemler ham veriyi çoğu zaman görmez. Bulguların güvenilirliği zamanla bağımsız doğrulamalarla pekişir.'),
  ('Bir doğum kayıt verisinde bildirilen boy ve kilo değerlerinin çoğu 0 ya da 5 ile bitiyor. Bu örüntü hakkında hangi çıkarım en akla yatkındır?', 'Ölçümler yuvarlanmış; basamak tercihi var', ['Boy ve kiloların gerçekte hep bu rakamlarla bitmesi', 'Verinin hiç bir hata taşımaması', 'Her bireyin aynı boyda olması'], 'Gerçek ölçümlerde son basamağın 0\'dan 9\'a kabaca eşit dağılması beklenir. 0 ve 5\'in fazlalığı, basamak tercihi ve yuvarlama sinyalidir.'),
  ('Bir başarı ölçüm çalışmasında okul sınıfındaki öğrencilerin başarısı, doğum aylarına göre karşılaştırılıyor ve yılın ilk aylarında doğanların daha başarılı olduğu görülüyor. Bu farkı en iyi hangisi açıklayabilir?', 'Sınıf içinde yaş farkı; ilk aylarda doğanlar büyüktür', ['Doğum ayının kişilik özelliklerini belirlemesi', 'Ay döngüsünün zekâyı etkilemesi', 'Başarı notlarının rastgele dağıtılması'], 'Aynı sınıfta aylar farkı, özellikle küçük yaşlarda belirgin bir gelişim farkı yaratır. Bu fark, doğum ayının nedensel bir etkisi değil, sınıf seviyesi ile yaş arasındaki ilişkiden gelir.'),
  ('Bir veri analizinde eksik gelir yanıtları sıfır olarak kodlanmış ve ortalama gelir hesaplanırken bu sıfırlar da dahil edilmiştir. Ortalama gelir için ne beklenir?', 'Gerçek ortalamadan düşük çıkar', ['Gerçek ortalamadan yüksek çıkar', 'Gerçek ortalamayla aynı çıkar', 'Hesaplanamaz hâle gelir'], 'Bilinmeyen değerler sıfır gibi işlendiğinde ortalama aşağı çekilir. Eksik değerler ayrı kodlanmalı ve analizde dışarıda bırakılmalı ya da uygun biçimde ele alınmalıdır.'),
  ('Bir ankette cinsiyet \'kadın = 1, erkek = 2\' olarak kodlanmış ve bir analist bu sütunun ortalamasını alıp \'1,4\' bulmuştur. Bu sayı hakkında hangisi doğrudur?', 'Yalnızca kodların ortalamasıdır; anlamsızdır', ['Kadın ve erkek ağırlığının kesin göstergesidir', 'Cinsiyetin ortalamasını gösteren yeni bir kategoridir', 'Veri hatası değildir; her tür veride ortalama anlamlıdır'], 'Kategorik kodlar yalnız etiket olduğundan sayısal işlemler anlam taşımaz. Ancak kodlar 0/1 ise ortalama, o kategorinin oranını verir.'),
  ('Posta kodları sayısal alana çevrildiğinde \'01234\' gibi baştaki sıfırlar kayboluyor ve kodlar farklı yerleri gösterir hâle geliyor. Bu örnek veri hazırlama için hangi dersi verir?', 'Tanımlayıcılar sayı değil metin saklanmalıdır', ['Posta kodlarının hiçbir zaman kullanılmaması gerektiği', 'Baştaki sıfırın anlamsız olduğu', 'Sayısal alanın daha güvenilir olduğu'], 'Posta kodu gibi tanımlayıcılar üzerinde toplama ya da ortalama alınmaz; sıfırla başlayan değerler sayıya çevrilince bilgi kaybolur. Türleri baştan doğru tanımlamak gerekir.'),
  ('Bir öğrencinin \'sıcaklık 10 °C\'den 20 °C\'ye çıktı, yani iki kat ısındı\' demesi neden yanlıştır?', 'Celsius\'ta gerçek sıfır yok; oran anlamsız', ['Sıcaklık hiçbir zaman ölçülemez ve sayıya çevrilemez', 'Celsius ölçeği yalnızca soğuk için kullanılır', 'Sıcaklık artışları her zaman çarpılarak ifade edilir'], 'Aralık ölçeğinde (Celsius) sıfır keyfîdir; \'iki kat\' ifadesi oran ölçeğinde (Kelvin) anlam taşır. Ölçek türü, hangi işlemlerin yorumlanabileceğini belirler.'),
  ('Bir araştırmada kullanılan veri sözlüğü (kod kitabı) yoksa ve sütun adları \'V1, V2, V3\' gibi anlamsızsa bu durum veri okuryazarlığı açısından hangi sorunu yaratır?', 'Yanlış yorum riski artar', ['Verilerin sayısal olarak bile okunamaması', 'Analizlerin otomatik olarak doğru çıkması', 'Birimlerin kendiliğinden belirlenmesi'], 'Değişkenin neyi ölçtüğü, birimi ve kodlaması bilinmeden doğru analiz yapılamaz. Veri sözlüğü, şeffaf ve yeniden üretilebilir araştırmanın temel parçasıdır.'),
  ('İki farklı araştırma, \'gençlik\' kavramını biri 15-24, diğeri 15-34 yaş arası tanımlayarak \'genç işsizlik oranı\'nı hesaplıyor ve farklı sonuçlar buluyor. Bu farklılık neden bu iki sonucun çelişkili olduğunu göstermez?', 'Tanımlar farklıdır', ['Biri kesinlikle yanlış hesaplanmıştır', 'Yaş grupları işsizliği hiç etkilemez', 'İşsizlik oranı hiçbir zaman gençlerde ölçülemez'], 'Farklı yaş aralığı, farklı işgücü yapısı demektir. Sonuçları karşılaştırmadan önce kavram ve ölçütlerin aynı olduğundan emin olunmalıdır.'),
  ('Bir hastalığın \'prevalans\' ve \'insidans\' kavramları arasındaki fark nedir?', 'Prevalans mevcut vaka, insidans yeni vaka oranıdır', ['İkisi aynı anlama gelir', 'Prevalans yeni vakaları, insidans mevcut vakaları gösterir', 'Prevalans yalnız ölümleri, insidans yalnız iyileşenleri sayar'], 'Prevalans, belirli bir anda hastalığı olanların oranıdır; insidans ise belli bir dönemde yeni hastalananların oranıdır. Uzun süren hastalıklarda prevalans, insidanstan çok yüksek olabilir.'),
  ('Bir şirketin sağlık programına katılanlar katılmayanlara göre daha az hastalanıyor. Programa katılımın isteğe bağlı olması bu sonucu nasıl etkiler?', 'Motive kişiler katılıyor olabilir', ['Katılımın isteğe bağlı olması sonucu daha güvenilir yapar', 'Katılım, sonuçla hiçbir şekilde ilişkili değildir', 'Katılanların sayısı etkisizdir ve sonuç şansa bağlıdır'], 'Gönüllü katılımcılar, zaten sağlıklı alışkanlıkları olan kişilerdir (sağlıklı katılımcı yanlılığı). Rastgele atama olmadan program etkisi saptanamaz.'),
  ('Bir yatırım aylık %10 getiri sağlıyor. \'Bu yatırım yılda %120 kazandırır\' diyen kişinin hatası nedir?', 'Bileşik işler; yıllık getiri yaklaşık %214\'tür', ['Aylık getiriler yıllık getirinin tamamen aynısıdır', 'Yıllık getiri %100\'ü hiçbir zaman aşamaz', 'Aylık getiri hiçbir zaman yıllığa çevrilemez'], '1,10^12 ≈ 3,14 olduğundan yıllık getiri yaklaşık %214\'tür. Bileşik büyümede toplama yerine çarpma yapılır.'),
  ('Bir ekonomi haberinde \'enflasyon %20\'den %15\'e düştü; fiyatlar geriledi\' deniyor. Bu yorum için hangisi doğrudur?', 'Fiyatlar hâlâ artıyor, yalnız hız yavaşladı', ['Fiyatlar gerçekten düşmüştür ve ucuzlama yaşanmıştır', 'Enflasyon %15 olduğunda fiyatlar sabit kalır', 'Enflasyonun düşmesi fiyatların %5 gerilemesi demektir'], 'Enflasyon, fiyat düzeyindeki yıllık artış oranıdır; %15 olduğu için fiyatlar yine artmaktadır. Düşen şey hızdır, düzey değildir (dezenflasyon).'),
  ('Bir yatırım dergisi, \'basit faizle %7 getirilen 10 yıllık yatırım yaklaşık %70, bileşik faizle yaklaşık %97 kazandırır\' diyor. Aradaki fark neden doğmaktadır?', 'Kazanılan faiz de faiz getirir', ['Bileşik faizde ana para her yıl düşer', 'Bileşik faiz yalnızca bankalarda kullanılır', 'Basit faizde ilk yıl hiç faiz verilmez'], '1,07^10 ≈ 1,97\'dir; ana paraya eklenen faiz sonraki yıl faiz getirir. Basit faizde ise yalnız ana para faiz kazanır.'),
  ('Bir şirketin kâr marjı %5\'tir ve geliri iki katına çıkarken kâr marjı değişmiyor. Kâr tutarı için ne söylenebilir?', 'Kâr tutarı da iki katına çıkar', ['Kâr tutarı değişmez, çünkü marj sabittir', 'Kâr tutarı yarıya iner', 'Kâr tutarı beş kat artar'], 'Kâr = gelir × marj olduğundan marj sabitken gelir iki katına çıkınca kâr da iki katına çıkar. Marj bir oran, kâr ise mutlak tutardır; ikisi karıştırılmamalıdır.'),
  ('Bir basketbolcu, 3 maçlık bir seride iki maçta 30\'dan fazla sayı atıyor ve antrenör \'artık yıldız oldu\' diyor. Hangi çıkarım en temkinlidir?', 'Üç maç yetmez; daha uzun örneklem gerekir', ['Üç maç, oyuncunun ortalamasını kesin olarak değiştirir', 'İki maç yeterince büyük bir örneklem oluşturur', 'Seri sonuçlar her zaman yeteneği gösterir'], 'Kısa serilerde oran ve ortalamalar şansla büyük dalgalanır. Yetenek tahmini için daha çok maçtan oluşan örneklem gerekir.'),
  ('Bir ülke \'milli gelir 5 yılda %20 arttı\' diyor ve nüfus aynı dönemde %25 artmıştır. Kişi başına milli gelir için hangisi doğrudur?', 'Kişi başına milli gelir azalmıştır', ['Kişi başına milli gelir artmıştır, çünkü toplam artmıştır', 'Kişi başına milli gelir %5 artmıştır', 'Kişi başına milli gelir değişmemiştir'], 'Kişi başına gelir 1,20 / 1,25 = 0,96 katına iner (%4 azalma). Toplam büyüme, nüfustan daha yavaşsa kişi başına gelir düşer.'),
  ('Bir yatırım uzmanı \'son 10 yılın ortalama getirisi %8\'dir, o hâlde gelecek yıl da %8 getirecektir\' diyor. Bu çıkarımın hangi hatası vardır?', 'Tek yılın sonucu ortalamayla garanti edilmez', ['Ortalama getiriler hiçbir zaman hesaplanamaz', 'Gelecek yılın getirisi her zaman geçmişin tersidir', 'Yıllık getiri yalnız birkaç ayda ölçülebilir'], 'Ortalama, yıllık sonuçların çok farklı olabileceğini gizler. Tek yılın getirisi büyük sapmalar gösterebilir; ortalama bu yıl için bir tahmin olsa da kesin bir sonuç değildir.'),
  ('Bir şirket \'Kâr %200 arttı\' diyor; geçen yıl kâr 1 milyon, bu yıl 3 milyon lira. Hesabın doğruluğu ve yorumu hakkında hangisi söylenebilir?', 'Doğru, ama taban küçüktür', ['Yanlıştır, doğru artış %300\'dür', 'Doğru değildir, çünkü kâr yüzdeyle ifade edilemez', 'Doğrudur ve mutlak tutarın verilmesi gereksizdir'], '(3 − 1) / 1 = %200\'dür; ancak 1 milyonluk bir taban küçük olabilir. Yüzdelerle birlikte mutlak tutarlar da verilmelidir.'),
  ('Bir kişi, sokakta karşısına çıkan ilk 50 kişiye anket yaparak \'rastgele bir örneklem aldım\' diyor. İstatistik dilinde \'rastgele örnekleme\' neden bu anlama gelmez?', 'Her birimin seçilme şansı bilinen olasılıkla belirlenmemiştir', ['Sokaktaki kişilerin sayıca çok az olması örneği geçersiz kılar', 'Örneklemin 50 kişi olması rastgeleliği tamamen ortadan kaldırır', 'İlk karşılaşılan kişiler her zaman aynı yaş grubundan olur'], 'Rastgele örneklemede her birimin seçilme olasılığı bilinir ve şansa bırakılır. \'Gelişigüzel\' ya da kolay ulaşılan örnekleme, bu garantiyi sağlamaz.'),
  ('Gündelik dilde \'ortalama bir öğrenci\' ifadesi çoğu kez \'tipik öğrenci\' anlamında kullanılır. İstatistikte \'ortalama\' terimi ise tek bir ölçüyü mü ifade eder?', 'Hayır; ortalama, medyan ve mod ayrı ölçülerdir', ['Evet; ortalama yalnız aritmetik ortalamadır ve başka ölçü yoktur', 'Evet; ortalama her zaman medyana eşit olan değerdir', 'Hayır; ortalama yalnızca en çok tekrar eden değerdir'], 'Haberlerde \'ortalama\' ifadesinin hangi ölçüyü kastettiği belirtilmezse, sonuçlar yanıltıcı olabilir. Çarpık dağılımlarda aritmetik ortalama ile medyan çok farklıdır.'),
  ('Bir mağaza \'indirim %70\'e kadar\' ilanı veriyor. Bu ifadeden çıkarılabilecek en doğru sonuç hangisidir?', 'En yüksek indirim %70\'tir', ['Bütün ürünlerde indirim tam olarak %70\'tir', 'Ürünlerde indirim yapılmamıştır', 'Ürünlerin yarısında indirim %70\'tir'], '\'… kadar\' ifadesi üst sınırı bildirir; ortalama indirimi ya da kaç ürünün bu orana sahip olduğunu bildirmez. Gerçek indirim dağılımı için ürün bazında bilgi gerekir.'),
  ('Bir anket haberinde \'Nüfusun %40\'ı X\'i destekliyor\' denirken ankete yalnızca internet kullanıcıları katılmıştır. Bu ifade için hangi düzeltme gereklidir?', 'Katılımcıların %40\'ı diye yazılmalı', ['Hiçbir düzeltme gerekmez; çünkü yüzde doğrudur', '\'Nüfusun %80\'i\' biçiminde yazılmalıdır', 'Yüzde yerine yalnızca sayı verilmelidir'], 'Sonuç, örneklemin temsil ettiği gruba atfedilmelidir. İnternet kullanıcıları nüfusun tamamı değildir; \'nüfusun %40\'ı\' ifadesi kapsam dışı bir genellemedir.'),
  ('\'Üç kişiden biri\' ifadesi yüzde olarak %33 ile eşleştirilirse bu eşleştirme için hangisi söylenebilir?', 'Yaklaşık doğrudur; yuvarlama yapılmıştır', ['Tam olarak doğrudur; çünkü 1/3 tam olarak %33\'tür', 'Tamamen yanlıştır; çünkü 1/3 %50\'dir', 'Hiçbir yuvarlama içermez; çünkü kesirler hep tam sayıdır'], '1/3 = 0,3333... olduğundan %33 yuvarlanmış bir değerdir. Yuvarlamanın büyüklüğü, özellikle küçük paydalarda sonuç yorumlamasını etkileyebilir.'),
  ('\'Normal\' sözcüğü gündelik dilde \'olağan\' anlamına gelirken istatistikte \'normal dağılım\' belirli bir çan biçimli dağılımı anlatır. Bu fark için hangisi doğrudur?', 'Normal dağılmama, veri hatası demek değildir', ['Normal dağılmayan veri her zaman hatalıdır', 'Normal dağılım yalnızca sağlıklı kişilerde görülür', 'Her gerçek veri kümesi normal dağılır'], 'Gelir, bekleme süresi gibi birçok değişken doğal olarak çarpık dağılır. Normal olmama, bir veri problemi değil, değişkenin yapısal özelliğidir.'),
  ('Bir araştırmacı \'sonuçlarım önemsiz değil\' diyor. Bu ifade için hangi yorum en dikkatlidir?', 'Belirsiz; etki büyüklüğü verilmeli', ['Sonuç kesinlikle çok önemlidir', 'Sonuç kesinlikle önemsizdir', 'Sonuç yalnız p-değeri 0,5 ise önemlidir'], '\'Önemsiz değil\' ifadesi ne kadar önemli olduğunu söylemez; küçük bir etki de \'önemsiz değil\' diye adlandırılabilir. Rakamsal etki ve belirsizlik verilmelidir.'),
  ('Bir yatırım broşüründe \'fiyat %50 düştü\' ve başka bir yerde \'fiyat yarıya indi\' ifadeleri geçiyor. Bu iki ifade için hangisi doğrudur?', 'İkisi de aynı değişimi anlatır', ['İkincisi birincisinden daha büyük bir düşüştür', 'Birincisi ikincisinden daha büyük bir düşüştür', 'İkisi de farklı ölçülere dayanır ve kıyaslanamaz'], 'Yarıya inmek, %50 azalmak demektir; iki ifade de aynı büyüklüğü anlatır. Sözcük değişimi, ölçüyü değiştirmez.'),
  ('Bir haber \'Satışlar bu yıl %25 arttı ve toplamda 5 puanlık pazar payı kazandık\' diyor. Burada \'%25\' ile \'5 puan\' arasındaki temel fark nedir?', '%25 göreli değişim, 5 puan mutlak farktır', ['İkisi de göreli değişimdir ve aynı anlama gelir', 'İkisi de mutlak farktır ve aynı anlama gelir', '%25 mutlak fark, 5 puan ise göreli değişimdir'], 'Yüzde değişim bir taban değere göre göreli büyüklüktür; yüzde puan ise iki oran arasındaki farkın kendisidir. İkisini karıştırmak sonucu olduğundan büyük ya da küçük gösterebilir.'),
  ('Bir kişi, bir havuzun ortalama derinliğinin 1,5 m olduğunu duyunca \'çocuğum güvenle yüzebilir\' diyor. İstatistik okuryazarlığı açısından en önemli eksik bilgi nedir?', 'Yayılım ve en derin nokta', ['Havuzun rengi', 'Havuzun yapılış yılı', 'Havuz kenarındaki ağaç sayısı'], 'Ortalama, aşırı derin ya da sığ bölümleri gizleyebilir. Güvenlik gibi uç değerlerin önemli olduğu durumlarda en küçük ve en büyük değerler bilinmelidir.'),
  ('Bir araştırmacı, sınava giren 300 öğrencinin ortalama puanını 62 olarak raporluyor ve \'öğrencilerin çoğu 62 aldı\' sonucuna varıyor. Bu çıkarım için hangisi söylenebilir?', 'Ortalama, hiçbir öğrencinin puanı olmayabilir', ['Ortalama her zaman en sık görülen puanı verir', 'Ortalama, öğrencilerin yarısının tam olarak 62 aldığı anlamına gelir', 'Ortalama, tüm öğrencilerin puanının 62 olduğunu gösterir'], 'Ortalama bir özetleyici sayıdır; verinin içindeki bir değer olması gerekmez. En sık görülen değer mod, ortadaki değer medyandır.'),
  ('Bir olayın gerçekleşme olasılığı %20\'dir. Bu olayın odds değeri (lehine : aleyhine) nedir?', '1:4', ['1:5, çünkü olasılığın tersi alınır', '1:2, çünkü olasılık ikiye bölünür', '2:1, çünkü %20 küçük bir orandır'], 'Olasılık 0,20 iken odds = 0,20 / 0,80 = 1/4\'tür; yani lehine 1, aleyhine 4. Olasılık küçükken odds ile olasılık yakındır, büyüdükçe ayrışır.'),
  ('Bir hizmet \'yüzde 99,9 çalışma süresi\' garantisi veriyor. Bir yılda (8760 saat) yaklaşık kaç saatlik kesinti bu garantiyle uyumludur?', 'Yaklaşık 8,8 saat', ['Yaklaşık 88 saat, çünkü kesinti payı %1\'dir', 'Yaklaşık 0,9 saat', 'Yaklaşık 87,6 gün'], 'Kesinti payı %0,1\'dir; 8760 × 0,001 ≈ 8,76 saat. Yüksek görünen yüzdeler, yıllık sürelere çevrildiğinde anlamları daha net anlaşılır.'),
  ('Bir kurumun beş adımlı bir onay süreci vardır ve her adımda hatasız geçiş olasılığı %95\'tir. Beş adımın hepsinde hata olmaması olasılığı yaklaşık kaçtır?', 'Yaklaşık %77', ['Yaklaşık %95, çünkü adım olasılıkları ortalanır', 'Yaklaşık %90', 'Yaklaşık %25'], '0,95^5 ≈ 0,774\'tür. Adımlar arttıkça toplam başarı olasılığı, her adımın olasılığından belirgin biçimde düşer.'),
  ('Bir kişi, ortalama 16 nefes/dakika hızıyla 80 yıl yaşadığında ömrü boyunca yaklaşık kaç nefes alır?', 'Yaklaşık 700 milyon', ['Yaklaşık 7 milyon, çünkü ömür boyu nefes sayısı çok küçüktür', 'Yaklaşık 70 milyar', 'Yaklaşık 7 trilyon'], '16 × 60 × 24 × 365 × 80 ≈ 6,7 × 10^8\'dir. Fermi tahminleri, büyüklük mertebesini hızlıca belirlemeyi sağlar.'),
  ('Bir kalp dakikada ortalama 70 kez atıyorsa, 80 yıllık bir yaşamda yaklaşık kaç kez atar?', 'Yaklaşık 3 milyar', ['Yaklaşık 300 milyon', 'Yaklaşık 30 milyar', 'Yaklaşık 300 bin'], '70 × 60 × 24 × 365 × 80 ≈ 2,9 × 10^9\'dur. Büyük sayıların mertebesini, birimleri çarparak tahmin etmek mümkündür.'),
  ('Bir trilyon saniye yaklaşık kaç yıla karşılık gelir?', 'Yaklaşık 31.700 yıl', ['Yaklaşık 31,7 yıl', 'Yaklaşık 3.170 yıl', 'Yaklaşık 317.000 yıl'], '10^12 / (365,25 × 86.400) ≈ 31.700 yıldır. Milyar ile trilyon arasındaki bin kat fark, sezgilere çarpıcı gelir.'),
  ('Bir klinik denemede iki ilacın etkisi, her biri 5 kişiden oluşan iki grupta karşılaştırılıyor ve fark bulunamıyor. Bu \'fark yok\' sonucu hakkında en doğru yorum nedir?', 'Küçük örneklem eşitliği göstermez', ['İlaçların eşit olduğu kesin olarak kanıtlanmıştır', 'Çalışmanın hiçbir zaman yapılmaması gerektiği', 'Beş kişi yeterli bir örneklemdir'], 'Düşük güç nedeniyle gerçek farklar bile saptanamayabilir. Etkisizlik iddiası için yeterli örneklem ve güven aralığı gerekir.'),
  ('Bir şirketin ürün hata oranı yılda %2\'den %1\'e düşüyor. Şirket \'hata oranını %50 azalttık\' derken müşteri \'yalnızca 1 puan azalmış\' diyor. İki ifade için hangisi doğrudur?', 'İkisi de doğrudur; biri göreli, diğeri mutlak farktır', ['Yalnızca şirket doğrudur, çünkü ikisi aynı ölçüdür ve kıyaslanır', 'Yalnızca müşteri doğrudur', 'İkisi de yanlıştır'], 'Göreli azalma (2−1)/2 = %50, mutlak azalma 1 yüzde puandır. Hangi ifadenin seçildiği, aynı değişimin etkisini büyük ya da küçük gösterir.'),
  ('Bir gürültü kaynağının şiddeti 60 desibelden 80 desibele çıkıyor. Ses gücü (yoğunluğu) kaç kat artmıştır?', '100 kat', ['20 kat, çünkü fark doğrusal alınır', '2 kat, çünkü dBel logaritmaktır ama oran korunur', '1,33 kat, çünkü oran 80/60\'tır'], 'Her 10 dB, gücü 10 kat artırır; 20 dB\'lik fark 10² = 100 kattır. Logaritmik ölçeklerde farklar çarpımsal etkileri gizler.'),
  ('Bir çözeltinin pH değeri 3\'ten 6\'ya çıkıyor. Hidrojen iyonu derişimi nasıl değişir?', '1000 kat azalır', ['3 kat azalır, çünkü pH farkı üç birimdir', '2 kat azalır, çünkü pH oranı 6/3\'tür', '30 kat azalır, çünkü her birim on kat değil on kat artar'], 'pH logaritmik bir ölçektir; her birim derişimi 10 kat değiştirir. Üç birimlik fark 10³ = 1000 katlık değişim demektir.'),
  ('Bir soğuk kış gününde bir kişi \'Hava bugün dondurucu, küresel ısınma yok demek ki\' diyor. Bu çıkarım hava ve iklim ayrımı açısından neden zayıftır?', 'Tek günün değişkenliği eğilimi çürütmez', ['Soğuk günlerin hiçbir zaman yaşanmaması', 'İklimin yalnız bir günlük veriyle belirlenmesi', 'Sıcaklığın hiçbir zaman ölçülememesi'], 'Hava günlük dalgalanmaları, iklim ise uzun dönemli ortalama davranışı anlatır. Tek bir uç gözlem, eğilimin varlığını ya da yokluğunu göstermez.'),
  ('Bir kentte araç sayısı artmış, kaza sayısı da artmıştır; başkan \'artan araç sayısı güvenliği düşürüyor\' diyor. Hangi ek ölçü, bu yorumu sınamak için en gerekli olanıdır?', 'Araç-km başına kaza oranının seyri', ['Kentte yaşayan kişilerin ayakkabı numaraları', 'Başkanın görev süresi', 'Araçların renk dağılımı'], 'Kaza sayısının araç sayısıyla artması beklenir; güvenliğin düşüp düşmediğini oran gösterir. Oran sabit ya da düşükse, kentin \'daha tehlikeli\' olduğu söylenemez.'),
  ('Bir araştırmada yeni bir ders kitabı kullanan 20 okulun ortalama notu bir önceki yıla göre artıyor. Aynı dönemde kitabı kullanmayan 20 okulda da ortalama not benzer miktarda artıyor. Kitabın etkisi için ne söylenebilir?', 'Artış kitaptan söylenemez', ['Kitap kesin olarak etkilidir', 'Kitap kesin olarak zararlıdır', 'Kitabın etkisi iki kat büyüktür'], 'Karşılaştırma grubundaki benzer artış, genel bir eğilimi (ör. sınav kolaylığı, zaman) gösterir. Kitaba özgü etki, iki grup arasındaki fark ile ölçülür.'),
  ('1747\'de James Lind, iskorbütlü 12 denizciyi altı çifte ayırıp her çifte farklı bir tedavi verdi ve narenciye alan çiftin hızla iyileştiğini gördü. Bu çalışma tasarımı hakkında hangisi doğrudur?', 'Kontrol var, ama örneklem çok küçüktür', ['Örneklem büyüklüğü bugünkü deneylerden büyüktü', 'Tedaviler rastgele atanmıştı ve kör yürütülmüştü', 'Çalışma hiçbir karşılaştırma içermiyordu'], 'Lind, benzer hastaları paralel gruplara ayırarak erken bir kontrollü karşılaştırma yaptı. Ancak 12 kişilik örneklem, bugünkü standartlara göre çok küçüktür.'),
  ('Bir şirket yeni yazılım projesinin süresini ve maliyetini tahmin ederken kendi ekibinin güçlü yanlarına odaklanıyor. Planlama yanılgısını azaltmak için en etkili yöntem hangisidir?', 'Benzer geçmiş projelerin gerçek süreleri', ['Ekip üyelerini daha iyimser olmaya teşvik etmek', 'Tahmini sürelere sürekli yeni özellik eklemek', 'Önceki projeleri unutmak'], 'Dış bakış (referans sınıfı tahmini), benzer projelerin gerçekleşen sonuçlarına dayanır ve iç bakışın iyimserliğini dengeler.'),
  ('Bir yatırımcı, bir hisse senedinin düşüşünü sonradan \'şirketin liderlik sorunları nedeniyle olacağı belliydi\' diye açıklıyor; düşüşten önce bu görüşü hiç dile getirmemişti. Bu tür sonradan uydurulan açıklamalara ne ad verilir?', 'Anlatı yanılgısı', ['Hayatta kalma yanlılığı', 'Kumarbaz yanılgısı', 'Ekolojik yanılgı'], 'Sonuç bilindikten sonra olayları tutarlı bir nedensel hikâyeye bağlamak kolaydır; bu hikâye olayın öngörülebilir olduğu izlenimini verir. Gerçek tahmin, olaydan önce yapılandır.'),
  ('Bir basın bülteni \'Kırmızı et yiyenlerde bir hastalık riski %20 daha fazla\' diyor; çalışmanın örneklemi 3.000 kişi ve izlem süresi 6 yıldır. Habere güvenmeden önce okurun sorması gereken ilk soru hangisidir?', 'Başlangıç riski nedir?', ['Haber kaç kelimeden oluşuyor?', 'Haberin yazarı hangi gazetede çalışıyor?', 'Hastalığın adı kaç harften oluşuyor?'], '%20\'lik göreli artışın mutlak etkisi başlangıç riskine, güvenilirliği de çalışma tasarımına ve karıştırıcı kontrolüne bağlıdır.'),
  ('Bir radyo programında \'Dinleyicilerin %90\'ı kararlarımızı destekliyor\' deniyor; destek, arayan kişilerden alınmış. Bu oran için hangisi söylenebilir?', 'Gönüllü seçilmiş kişilerdir; temsil etmez', ['Dinleyici kitlesinin tamamını güvenle temsil eder', 'Hata payı sıfırdır', 'Arayan sayısı fazlaysa her zaman doğrudur'], 'Arama yapan kişiler, güçlü görüşü olan gönüllülerdir. Seçilmiş bir örneklemin yüzdesi, genel kitle hakkında güvenilir bilgi vermez.'),
  ('Atmosferdeki bir gazın derişimi 400 ppm (milyonda 400 parça) olarak veriliyor. Bu derişim yüzde olarak kaçtır?', '%0,04', ['%4', '%0,4', '%0,004'], '400 / 1.000.000 = 0,0004 = %0,04\'tür. Çok küçük oranlar ppm gibi birimlerle verildiğinde yüzdeye çevirmek ondalık kaymalara dikkat gerektirir.'),
  ('Bir ülkede kadın ve erkek nüfusunun oranı 1\'e 1,1\'dir (her kadına karşı 1,1 erkek). Nüfusun yüzde kaçı kadındır?', 'Yaklaşık %47,6', ['Yaklaşık %50, çünkü yarı yarıya bölünür', 'Yaklaşık %52,4', 'Yaklaşık %45'], 'Toplam pay 1 + 1,1 = 2,1\'dir; kadın payı 1 / 2,1 ≈ 0,476\'dır. Oran (kadın:erkek) ile yüzde farklı ifadelerdir.'),
  ('Bir fabrikanın kusur oranı %2\'den %3\'e çıkıyor. Bu artış hangi iki biçimde doğru anlatılır?', '1 yüzde puan, göreli olarak %50 artış', ['1 yüzde puan, göreli olarak %1 artış', '%1 puan, göreli olarak %3 artış', '50 yüzde puan, göreli olarak 1 yüzde puan artış'], 'Mutlak fark 3 − 2 = 1 yüzde puandır; göreli artış 1 / 2 = %50\'dir. İki ifade de doğrudur ama etkiyi farklı büyüklükte gösterir.'),
  ('Bir internet sitesinin ziyaretçileri \'dönüşüm oranı %2\'den %2,2\'ye çıktı, yani %10 arttı\' diyor. Bu ifade hakkında hangisi doğrudur?', 'Doğru, ama mutlak artış 0,2 puandır', ['Yanlıştır; artış %0,2\'dir', 'Yanlıştır; artış %20\'dir', 'Doğrudur ve mutlak artış %10 puandır'], '(2,2 − 2) / 2 = %10 göreli artıştır; mutlak artış 0,2 yüzde puandır. Küçük tabanlı oranlarda göreli artış büyük görünür.'),
  ('Bir gazeteci \'ölüm oranı bin kişide 12\'den bin kişide 9\'a düştü\' yazıyor. Bu düşüş yüzde kaç olarak ifade edilir?', '%25', ['%3, çünkü fark doğrudan alınır', '%12', '%75'], 'Düşüş 3 binde 12 tabanına göre 3/12 = %25\'tir. Binde 3\'lük mutlak düşüş, %0,3 puan demektir; göreli düşüş ise %25\'tir.'),
  ('Bir kişinin doktorda ölçülen ilk tansiyonu yüksek çıkıyor ve doktor \'evde ve ertesi gün tekrar ölçelim\' diyor. İkinci ölçümün genellikle daha düşük çıkması en çok hangi istatistiksel olguyla ilgilidir?', 'Ortalamaya dönüş; uç ölçüm kısmen rastlantıdır', ['Büyük sayılar yasası; ölçüm sayısı arttıkça değer kesinleşir', 'Kayıptan kaçınma; hastalar kötü sonuçtan korkar', 'Çıpalama; ilk sayıya yaklaşmak'], 'Yüksek bir tek ölçüm, gerçek değerle birlikte rastgele dalgalanmayı da içerir. Tekrar ölçüm, bu dalgalanmayı azaltır ve tanı kararı için daha güvenilir bir ortalama sağlar.'),
  ('Uçak kazalarının \'üçlü\' geldiğine dair yaygın inanç, art arda gelen üç kazanın bir \'seri\' olarak görülmesine dayanır. Bu inancı en iyi hangi olgu açıklar?', 'Rastgele olaylar da kümelenir', ['Kazaların mutlaka bir sonraki kazayı tetiklemesi', 'Kazaların hiç rastgele olmaması', 'Kazaların yalnızca üç ay içinde yaşanması'], 'Bağımsız olaylar zaman içinde eşit aralıklı dağılmaz; yoğunlaşmalar şansla da oluşur. Sonradan seçilen kümeler, kümelenmeyen dönemleri göz ardı eder.'),
  ('Rastgele yanıt tekniği gibi yöntemler, hassas sorularda hangi sorunu azaltmak için kullanılır?', 'Sosyal beğenirlik yanlılığını', ['Örnekleme çerçevesi hatasını, yani önceki örnekleme hatası', 'Ortalamaya dönüş etkisini', 'Üstel büyüme yanlılığını'], 'Katılımcının gerçek yanıtının gizli kaldığı bir yapı, utanç ya da çekince nedeniyle yanıt vermeme ya da çarpıtmayı azaltır. Bedeli, tahminin daha geniş bir belirsizlik taşımasıdır.'),
  ('Bir araştırmacı, katılımcılardan alınan bilgilendirilmiş onamda verilerin yalnızca belirtilen çalışma için kullanılacağı söylenmişken aynı veriyi sonradan farklı bir çalışmada kullanıyor. Bu durumda hangi etik ilke zedelenmiştir?', 'Amaç dışı veri kullanmama', ['Rastgele atama ilkesi', 'Örneklem büyüklüğü ilkesi', 'Hipotezin önceden belirtilmesi ilkesi'], 'Katılımcılar yalnızca açıklanan amaçlar için rıza gösterir; farklı bir kullanım yeniden onam ya da etik kurul değerlendirmesi gerektirir.'),
  ('Erkeklerin ortalama boyu kadınlarınkinden yaklaşık 13 cm fazladır. \'Her erkek her kadından uzundur\' sonucu neden yanlıştır?', 'İki dağılım örtüşür', ['Ortalama farkı hiçbir şey ifade etmez', 'Dağılımlar arasında örtüşme asla olmaz', 'Boy ortalamasının hesaplanamaması'], 'Grup ortalamaları arasındaki fark, bireyler arasındaki sıralamayı belirlemez. Dağılımlar örtüştüğü için bireysel karşılaştırmalar gruptan bağımsız yapılamaz.'),
  ('Bir ülkede ortalama hane geliri bir yıl içinde sabit kalırken ortalama hane büyüklüğü 4\'ten 3\'e düşüyor. Kişi başına gelir için ne söylenebilir?', 'Kişi başına gelir artmıştır', ['Kişi başına gelir azalmıştır', 'Kişi başına gelir değişmemiştir', 'Kişi başına gelir hesaplanamaz'], 'Aynı hane geliri daha az kişiye düştüğü için kişi başına gelir yükselir (ör. 4 kişide kişi başı 1/4, 3 kişide 1/3). Hane geliri ile kişi başı gelir farklı paydalar kullanır.'),
  ('Bir ülkenin kamu borcu sabit kalırken GSYH\'si %10 artıyor. Borcun GSYH\'ye oranı nasıl değişir?', 'Yaklaşık %9 azalır', ['Yaklaşık %10 azalır', 'Yaklaşık %10 artar', 'Hiç değişmez'], 'Oran 1 / 1,10 ≈ 0,909 katına iner; yani yaklaşık %9,1 azalır. Borç tutarı değişmese de oran, paydadaki büyümeyle düşer.'),
  ('İki sınıfın matematik ortalaması 70\'tir; birinde öğrencilerin puanları 65-75 arasında, diğerinde 20-100 arasında dağılıyor. \'İki sınıf eşit düzeydedir\' sonucu neden yetersizdir?', 'Dağılımlar çok farklıdır', ['Ortalamaların hiç hesaplanamaması', 'İki sınıfın öğrenci sayısının hiç bilinmemesi', 'Puanların yalnızca yüzde ile verilebilmesi'], 'Aynı ortalamaya sahip iki grup, çok farklı homojenlikte olabilir. Merkez ve yayılım ölçüleri birlikte sunulmalıdır.'),
  ('İki otobüs hattında ortalama bekleme süresi 10 dakikadır; birinde otobüsler tam 10 dakikada bir, diğerinde zamanlar çok düzensiz gelmektedir. Yolcu deneyimi bakımından hangi ifade daha doğrudur?', 'Düzensiz hatta deneyim daha değişkendir', ['İki hat yolcu için tamamen aynı deneyimi sağlar', 'Düzenli hat daha kötü bir deneyim sağlar', 'Düzensiz hat bekleme süresini sıfıra indirir'], 'Ortalama, bekleme süresi değişkenliğini göstermez. Düzensiz hatta bazen çok uzun beklenir; yolcu için güvenilirlik, ortalama kadar önemlidir.'),
  ('Bir mağaza zincirinin 100 şubesinden 3\'ü hırsızlık nedeniyle çok yüksek kayıp bildiriyor. Genel müdür \'ortalama kayıp yüksek\' diyor. Bu ortalama için hangisi doğrudur?', 'Birkaç uç şube ortalamayı yükseltiyor', ['Bütün şubelerde kayıp yüksektir', 'Ortalama kayıp, tipik şubeyi her zaman yansıtır', 'Şubelerde hiç kayıp yoktur'], 'Az sayıda uç değer ortalamayı yukarı çeker. Tipik şubenin durumu için medyan ve dağılım bilgisi daha uygundur.'),
  ('Bir araştırmada A ve B gruplarının ortalamaları arasındaki fark anlamlı bulunmuş ve etki büyüklüğü çok küçüktür. \'Sonuç önemli\' ifadesi için en doğru değerlendirme nedir?', 'Anlamlılık önemi göstermez', ['Anlamlılık her zaman büyük etkiyi gösterir', 'Küçük etki hiçbir zaman anlamlı çıkamaz', 'Önem yalnızca p-değeriyle ölçülür'], 'İstatistiksel anlamlılık, şansla açıklanamama ölçüsüdür; pratik önemi etki büyüklüğü, maliyet ve bağlam belirler.'),
  ('Bir kriz döneminde \'aşırı ölüm\' (excess mortality) kavramı nasıl hesaplanır?', 'Gözlenen ile beklenen ölümün farkı', ['Yalnızca krize bağlı ilan edilen ölümler toplanarak', 'Önceki yılın ölüm sayısı değiştirilmeden alınarak', 'Hastane yatışları ölüm sayısına bölünerek'], 'Beklenen sayı, önceki yıllardaki eğilim ve mevsim etkisiyle tahmin edilir. Böylece ölüm nedeninin kaydına ya da test kapasitesine bağlı olmayan toplam etki görülür.'),
  ('Bir abonelik uygulaması, kullanıcı memnuniyet anketini yalnızca hâlâ uygulamayı kullananlara gönderiyor ve %90 memnuniyet buluyor. Bu oranı hangi sorun şişirir?', 'Ayrılan kullanıcılar ankette yok', ['Kullanıcı sayısının fazla olması', 'Anketin çok kısa olması', 'Memnuniyet sorusunun sayısal olması'], 'Memnun olmayanlar uygulamayı bırakmış olabilir; yalnız kalanlara sormak, hayatta kalma yanlılığıdır. Ayrılanların nedenlerini de anlamak gerekir.'),
  ('Bir ürünün çevrimiçi puanı 50 yorumla 4,8, rakip ürünün puanı 5000 yorumla 4,6\'dır. Hangi ifade doğru bir değerlendirmedir?', 'Küçük örneklemdeki 4,8 daha belirsiz', ['4,8 kesinlikle daha iyidir, çünkü sayı büyüktür', 'İki puan her zaman eşittir', 'Yorum sayısı puan güvenilirliğini hiç etkilemez'], '50 yorumluk ortalama, 5000 yorumluk ortalamadan çok daha fazla dalgalanır. Yorum sayısı dikkate alınarak yapılan düzeltmeler, puanları karşılaştırmayı iyileştirir.'),
  ('Bir takviyenin kısa vadede (4 hafta) uyku kalitesini iyileştirdiği bildiriliyor. \'Uzun süre kullanmak da iyileştirir\' çıkarımı neden temkinle karşılanmalıdır?', 'Kısa vadeli etki kalıcı olmayabilir', ['Kısa vadeli çalışma hiçbir bilgi vermez', 'Takviyelerin hiçbir etkisi olamaz', 'Uyku kalitesi sayısal ölçülemez'], 'Kısa bir izlemede alışkanlık, plasebo ve geçici etkiler öne çıkar. Uzun vadeli etki, yan etki ve güvenlik için daha uzun izlem gerekir.'),
  ('Bir şehirde yeni bir bisiklet yolu açıldıktan sonra bisiklet kazaları artıyor. Belediye \'bisiklet yolu kazaları artırıyor\' diyor. Hangi ek ölçü bu yorumu değerlendirmeye en çok yarar?', 'Bisiklete binen kişi sayısına göre kaza oranı', ['Bisikletlerin renk dağılımı, çünkü bisiklet yollarında hep kaza olur', 'Yolun asfalt rengi', 'Belediyenin bütçesi'], 'Yol açıldıkça bisiklete binen sayısı arttıysa kaza sayısı artsa bile kişi başı risk azalmış olabilir. Maruziyete göre normalleştirilmiş oran gerekir.'),
  ('Bir kuruluş, \'çalışanların %80\'i işten memnun\' sonucunu, anketi yalnızca yöneticilerin dağıttığı ve imzalı yanıt istediği bir yöntemle elde etmiştir. Bu sonucun güvenilirliği hakkında en uygun yorum hangisidir?', 'Beyanlar sosyal beğenirliği artırır', ['İmzalı yanıt her zaman daha doğru yanıt sağlar', 'Yönetici dağıtımı örneklemi rastgele yapar', 'Memnuniyet hiçbir zaman ölçülemez'], 'Çalışanlar yönetime kendini kötü göstermemek için olumlu yanıt verebilir. Anonim ve bağımsız bir uygulama, sosyal beğenirlik etkisini azaltır.'),
  ('Bir öğretmen, 30 öğrencili sınıfa 5 puan ekleyerek \'yeni ortalama\' yayımlıyor; standart sapma değişmiyor. Not dağılımının biçimi ve yayılımı için ne söylenebilir?', 'Dağılım yalnız kaymıştır', ['Yayılım 5 puan artar, ve standart sapma beş puan artar', 'Dağılım tersine döner', 'Çarpıklık sıfırlanır'], 'Her değere sabit eklemek ortalamayı ve medyanı aynı miktarda kaydırır; standart sapma ve dağılım biçimi değişmez. Ortalamadaki artış, başarının arttığı anlamına gelmez.'),
  ('Bir şirketin çalışanlarından seçilen 10 kişilik bir grupta ortalama kıdem 8 yıl çıkıyor; seçim, şirketin \'en uzun süredir çalışan\' sicil listesinin ilk 10 sırasından yapılmıştır. Bu ortalama için hangisi doğrudur?', 'Kıdemi olduğundan uzun gösterir', ['Tüm çalışanların kıdemini olduğundan çok daha kısa gösterir', 'Tüm çalışanların kıdemini tam olarak gösterir', 'Hesaplanamaz, çünkü kıdem sayı değildir'], 'Listenin başından seçmek örneklemi en uzun kıdemlilere sınırlar. Rastgele örnekleme olmadığından ortalama genelleştirilemez.'),
  ('Çok kolay bir sınavda öğrencilerin çoğu tam puana yakın not alıyor. Bu \'tavan etkisi\'nin bir araştırma için sonucu ne olur?', 'Yetenek farkları puanlara yansımaz', ['Yetenek farkları büyür ve kolayca görünür', 'Puanlar hiçbir ilişkiyi göstermez', 'Standart sapma artar'], 'Ölçek üst sınıra dayandığında yüksek yetenekliler ayrışamaz; değişkenlik ve korelasyonlar yapay olarak azalır.'),
  ('Bir ölçek çok zor sorulardan oluşuyor ve çoğu kişi sıfıra yakın puan alıyor. Bu \'taban etkisi\'nin ölçeğin ayırt ediciliği için sonucu nedir?', 'Düşük yetenekliler ayırt edilemez', ['Ölçek yüksek uçta duyarsızlaşır', 'Ölçek her uçta eşit duyarlı olur', 'Puanlar rastgele hâle gelir ve sıfır olur'], 'Çok zor sorular, düşük düzeydekilerin hepsini aynı (sıfır) puana yığar. Yetenek farkları puanlara yansımaz.'),
  ('Bir araştırma, bir ilacı kullanan 3 hastanın hepsinin iyileştiğini bildirip \'başarı oranı %100\' diyor. Bu orana ne kadar güvenilmelidir?', 'Çok az; üç gözlem yetmez', ['Tamamen, çünkü yüzde yüz kesin bir sonuçtur', 'Hiçbir zaman, çünkü başarı oranı bildirilemez', 'Yalnız ilaç ucuzsa'], 'Küçük n\'li oranlar çok geniş belirsizlik taşır; üç hastanın üçü iyileşse bile gerçek oran birkaç on yüzde düşük olabilir.'),
  ('Bir ankette katılımcıların %45\'i \'A markasını bilir\', %40\'ı \'B markasını bilir\' ve %25\'i \'ikisini de bilir\' yanıtını veriyor. İki markadan en az birini bilenlerin oranı kaçtır?', '%60', ['%85, çünkü örtüşme ayrıca eklenir', '%70', '%45'], 'En az birini bilenler: 45 + 40 − 25 = %60\'tır. Çift sayımı önlemek için örtüşme çıkarılır.'),
  ('Bir ülkede medyan yaş 20 yıl boyunca 25\'ten 35\'e çıkıyor. Bu artış, nüfusun yaş yapısı hakkında neyi gösterir?', 'Nüfus yaşlanmaktadır', ['Nüfus gençleşmektedir', 'Yaş yapısı değişmemektedir', 'Yalnızca çocuk sayısı artmaktadır'], 'Medyan yaşın artması yaşlı payının büyüdüğü anlamına gelir. Ölüm ya da kanser gibi yaşa bağlı olayların ham sayıları, risk artmasa da yükselebilir.'),
  ('Bir şirket \'müşterilerimizin %100\'ü memnun\' diyor ve yalnızca iki müşteriye sormuş. Bu ifadeyi dürüst bir raporlama için nasıl düzeltmek gerekir?', '\'İki müşteriden ikisi\' diye yazmak', ['Aynı ifadeyi %100 olarak sürdürmek, ve anketin yapıldığı yılı belirtmek', 'Yalnızca yüzdeyi büyütmek', 'Müşteri sayısını gizlemek'], 'Küçük payda ile verilen yüzde yanıltıcıdır; payın ve paydanın birlikte verilmesi okuyucuya doğru bir güven düzeyi verir.'),
  ('Bir ölçekte bazı maddeler olumlu, bazıları olumsuz yazılmıştır; ancak analizde olumsuz maddelerin puanları ters çevrilmeden toplanıyor. Bu hatanın sonucu ne olur?', 'Ölçeğin güvenirliği düşer', ['Ölçeğin güvenirliği artar', 'Toplam puan etkilenmez', 'Katılımcılar iyi yanıt verir'], 'Zıt yönlü maddeleri aynı yönde toplamak, karşıt eğilimleri birbirini götürmeye zorlar. Ters kodlama ihmal edilirse puan, kavramı yansıtmaz.'),
  ('Bir ülkenin ilk açıklanan GSYH büyüme tahmini %3,0 iken bir yıl sonra %2,2\'ye revize ediliyor. Bu revizyon ekonomik veri okuryazarlığı için ne öğretir?', 'İlk tahminler revize edilebilir', ['Revizyonlar hiç olmaz', 'İlk tahmin her zaman en doğrusudur', 'Revizyon, veri toplamanın yasak olduğunu gösterir'], 'Erken tahminler, sonradan gelen verilerle düzeltilir. Politika kararları alınırken ilk açıklamanın belirsizliği hesaba katılmalıdır.'),
  ('Bir şirket \'Başarılı CEO\'ların %90\'ı sabah 5\'te kalkıyor\' haberine dayanarak çalışanlarına erken kalkmayı öneriyor. Bu öneriye karşı en güçlü istatistiksel itiraz nedir?', 'Başarısızların oranı bilinmiyor', ['CEO sayısının fazla olması, ve başarılıların çoğunluğu', 'Saatin ölçülememesi', 'Başarının sayı olması'], 'Başarılıların ortak özelliği, o özelliğin başarısızlarda da yaygın olup olmadığını göstermeden bir şey kanıtlamaz. Doğru karşılaştırma grubu eksiktir.'),
  ('Bir spor kulübü, bir sezonda iki oyuncunun gol sayılarını karşılaştırıyor: A 10 maçta 6 gol, B 30 maçta 15 gol atmıştır. Maç başına gol bakımından hangisi yüksektir ve bu sonuç ne kadar güvenilirdir?', 'A yüksek ama 10 maç azdır', ['B\'nin oranı yüksektir ve sonuç tamamen kesindir', 'İkisi eşittir ve fark yoktur', 'A\'nın oranı düşüktür'], 'Maç başına gol A için 0,6, B için 0,5\'tir. Ancak A\'nın örneklemi küçük olduğundan oran şansla büyük değişir; fark güvenilir sayılamaz.'),
  ('Bir kentin 10 yıllık sıcaklık kaydında en sıcak yıl son yıldır. \'Rekor kırıldı, iklim hızla ısınıyor\' diyen birinin çıkarımı için en dikkatli yorum hangisidir?', 'Tek rekor yıl eğilim için yetmez', ['Rekor yıl her zaman eğilimin kesin kanıtıdır', 'Rekorlar hiçbir koşulda anlam taşımaz', 'On yıl tüm iklim tarihini kapsar'], 'Tek bir uç yıl, doğal değişkenliğin bir ifadesi olabilir. Eğilim için daha uzun seri, değişkenlik ve eğim tahmininin belirsizliği gerekir.'),
  ('Bir araştırmada A ve B maddelerini aynı anda alan hastalarda iyileşme gözleniyor. Araştırmacı \'A tek başına etkilidir\' sonucuna varıyor. Bu çıkarım için hangi tasarım eksikliği vardır?', 'Tek başına alan gruplar yok', ['Hasta sayısının hiç sayılamaması', 'İyileşmenin ölçülememesi', 'B maddesinin ücretsiz olması'], 'Birlikte uygulanan iki müdahalenin etkisini ayırmak için her birinin tek başına ve birlikte verildiği gruplar gerekir. Aksi hâlde etki A\'ya atfedilemez.'),
  ('Bir havuza her gün suyun aktığı hızın azalması \'havuzdaki su azalıyor\' anlamına gelir mi?', 'Hayır; seviye artabilir', ['Evet; akış azaldığında seviye düşer', 'Evet; akış ve seviye aynı kavramdır', 'Hayır; akış hiçbir zaman ölçülemez'], 'Akış (hız) ile stok (seviye) farklı büyüklüklerdir. Akışın azalması, yalnızca stoktaki değişimin hızının azaldığı anlamına gelir.'),
  ('Bir pazarın toplam büyüklüğü %20 artarken bir şirketin satışı %10 artıyor. Şirketin pazar payı nasıl değişir?', 'Azalır', ['Artar; çünkü satış artmıştır', 'Değişmez; çünkü satış artmıştır', 'Hesaplanamaz'], 'Pay = satış / pazar; 1,10 / 1,20 ≈ 0,917 katına iner. Mutlak büyüme, pazar payı kazancı anlamına gelmez.'),
  ('Bir sigortacı, poliçelerin yarısında hiç hasar olmadığını ve kalan yarıda hasar çok yüksek olduğunu gözlemliyor. \'Ortalama hasar\' için hangisi doğrudur?', 'Ortalama tipik poliçeyi yansıtmaz', ['Ortalama her poliçenin hasarını yansıtır', 'Medyan ve ortalama her zaman eşittir', 'Ortalama hiçbir zaman hesaplanamaz'], 'Çift tepeli ya da yığılmış dağılımlarda ortalama, hiçbir poliçenin gerçek hasarı olmayabilir. Prim hesabı için hem ortalama hem dağılım gerekir.'),
  ('Bir kent ile komşu kent arasında, nüfus 5 kat farklıyken kanser vaka sayıları da 5 kat farklıdır. Bu bilgiyle kanser riskinin iki kentte farklı olduğu söylenebilir mi?', 'Hayır; kişi başı oran aynıdır', ['Evet; vaka sayıları farklıdır', 'Evet; küçük kent daha güvenlidir', 'Hayır; çünkü vaka sayıları ölçülemez'], 'Vaka sayısı nüfusla orantılıysa kişi başına oran (ör. 100 bin kişide) aynıdır. Sayıları değil oranları karşılaştırmak gerekir.'),
  ('Bir fon yöneticisi \'işlemlerimizin %95\'inde kâr ettik\' diyor ancak toplam getirisi eksiye dönmüştür. Bu çelişkinin en olası nedeni nedir?', 'Kâr eden işlemler küçük, zarar edenler büyük', ['Kâr eden işlemlerin bulunmaması, ve işlemler hiç yapılmamıştır', 'Yüzde hesabının yapılamaması', 'Zararların hiç kaydedilmemesi'], 'Kazanç oranı, kazancın büyüklüğünü söylemez. Az sayıda büyük kayıp, çok sayıda küçük kazancı geçebilir.'),
  ('Bir şehirde 10 yılda hiç büyük deprem olmadığı için \'artık deprem riski yok\' diyen birinin çıkarımı için hangisi doğrudur?', 'Sessizlik riskin yokluğunu göstermez', ['10 yıl deprem riskinin sıfır olduğunu kanıtlar', 'Depremler her 10 yılda bir mutlaka olur', 'Risk yalnızca yaz aylarında vardır'], 'Dönüş süresi uzun olaylar için kısa gözlem süresi bilgi vermez. Sessiz dönemler, riskin sona erdiğini değil, olayın nadirliğini yansıtır.'),
  ('Bir haber, \'Üniversite mezunlarının işsizlik oranı %5, mezun olmayanların %9\'dur; demek ki üniversite işsizliği azaltır\' diyor. Bu çıkarımı zayıflatan bir olasılık hangisidir?', 'Aile ve yetenek farkı', ['Mezunların sayısı fazla olduğu için işsizlik oranı hesaplanamaz', 'Üniversite hiçbir ölçülebilir bilgi vermez', 'İşsizlik oranının sayı olması'], 'Üniversiteye gitme, aile geliri ve yetenek gibi etkenlerle ilişkilidir; bu etkenler işsizliği de etkiler. Gözlemsel fark tek başına nedensel bir etki göstermez.'),
  ('Aynı hastalık için iki ilaç karşılaştırılıyor; A ilacında hastaların %80\'i, B ilacında %70\'i iyileşiyor, fark anlamlı değil. Bu sonuç için hangisi doğru bir yorumdur?', 'Şansla açıklanabilir', ['A kesin olarak üstündür', 'İkisi tam olarak aynıdır', 'B kesin olarak üstündür'], 'Anlamsız bir fark, etkisizlik kanıtı değil; yeterli kanıtın olmadığı anlamına gelir. Güven aralığı ve örneklem büyüklüğü birlikte değerlendirilmelidir.'),
];
